  `protocol` varchar(255) NOT NULL DEFAULT '' COMMENT '协议all,tcp,udp,icmp',
  `port` varchar(255) NOT NULL DEFAULT '' COMMENT '端口范围',
  `ip` varchar(255) NOT NULL DEFAULT '' COMMENT '授权IP',
