  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '白名单状态0关闭1开启',
  `ip` text NOT NULL COMMENT '白名单IP',
  `private_key` text NOT NULL COMMENT '私钥',
  `create_time` int(11) NOT NULL DEFAULT '0' COMMENT '创建时间',
