  `module` varchar(100) NOT NULL DEFAULT '' COMMENT '插件模块路径,如:gateway支付接口/sms短信接口/mail邮件接口/addon插件',
  `plugin` varchar(100) NOT NULL DEFAULT '' COMMENT '插件',
  `description` text NOT NULL COMMENT '描述',
  PRIMARY KEY (`id`)
