  `plugin` varchar(100) NOT NULL DEFAULT '' COMMENT '插件',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COMMENT='会员中心权限表';

/*Data for the table `idcsmart_clientarea_auth` */


