  KEY `clientarea_auth_rule_id` (`clientarea_auth_rule_id`),
  KEY `clientarea_auth_id` (`clientarea_auth_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='会员中心权限规则对应表';

