CREATE TABLE `idcsmart_email_template` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '邮件模板ID',
  `name` varchar(100) NOT NULL DEFAULT '' COMMENT '模板名称',
  `subject` varchar(100) NOT NULL DEFAULT '' COMMENT '模板标题',
  `message` text NOT NULL COMMENT '模板内容',
  `attachment` text NOT NULL COMMENT '附件',
  `create_time` int(11) NOT NULL DEFAULT '0' COMMENT '创建时间',
  `update_time` int(11) NOT NULL DEFAULT '0' COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=36 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=COMPACT COMMENT='邮件模板表';

/*Data for the table `idcsmart_email_template` */


/*Table structure for table `idcsmart_feedback` */

DROP TABLE IF EXISTS `idcsmart_feedback`;

CREATE TABLE `idcsmart_feedback` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '意见反馈ID',
  `client_id` int(11) NOT NULL DEFAULT '0' COMMENT '用户ID',
  `feedback_type_id` int(11) NOT NULL DEFAULT '0' COMMENT '意见反馈类型ID',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT '标题',
  `description` text NOT NULL COMMENT '描述',
  `contact` varchar(255) NOT NULL DEFAULT '' COMMENT '联系方式',
  `attachment` text NOT NULL COMMENT '附件',
  `create_time` int(11) NOT NULL DEFAULT '0' COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `client_id` (`client_id`),
  KEY `feedback_type_id` (`feedback_type_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='意见反馈';

