  `qty` int(11) NOT NULL DEFAULT '0' COMMENT '配置项为数量类型时的数量',
  `repeat` int(11) NOT NULL DEFAULT '0' COMMENT '重复',
  PRIMARY KEY (`id`),
  KEY `host_id` (`host_id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4;

