/*Table structure for table `idcsmart_module_mf_cloud_limit_rule` */

DROP TABLE IF EXISTS `idcsmart_module_mf_cloud_limit_rule`;

CREATE TABLE `idcsmart_module_mf_cloud_limit_rule` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `product_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '商品ID',
  `rule` text NOT NULL COMMENT '规则json',
  `result` text NOT NULL COMMENT '结果json',
  `rule_md5` char(32) NOT NULL DEFAULT '' COMMENT '规则md5用于判断是否重复',
  `create_time` int(11) unsigned NOT NULL DEFAULT '0',
  `update_time` int(11) unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `rule_md5` (`rule_md5`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='限制规则表';

/*Data for the table `idcsmart_module_mf_cloud_limit_rule` */

/*Table structure for table `idcsmart_module_mf_cloud_line` */

DROP TABLE IF EXISTS `idcsmart_module_mf_cloud_line`;

CREATE TABLE `idcsmart_module_mf_cloud_line` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `data_center_id` int(11) NOT NULL DEFAULT '0' COMMENT '数据中心ID',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT '线路名称',
  `bill_type` varchar(20) NOT NULL DEFAULT '' COMMENT 'bw=带宽计费,flow=流量计费',
  `bw_ip_group` varchar(10) NOT NULL DEFAULT '' COMMENT '带宽IP分组',
  `defence_enable` tinyint(3) NOT NULL DEFAULT '0' COMMENT '是否启用防护',
  `defence_ip_group` varchar(10) NOT NULL DEFAULT '' COMMENT '防护IP分组',
  `ip_enable` tinyint(3) NOT NULL DEFAULT '0' COMMENT '是否启用附加IP价格',
  `create_time` int(11) NOT NULL DEFAULT '0',
  `link_clone` tinyint(3) NOT NULL DEFAULT '0' COMMENT '链接创建(0=否,1=是)',
  `order` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `gpu_name` varchar(255) NOT NULL DEFAULT '',
  `gpu_enable` int(1) unsigned NOT NULL DEFAULT '0' COMMENT '是否启用GPU',
  `ipv6_enable` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '是否启用IPv6',
  PRIMARY KEY (`id`),
  KEY `data_center_id` (`data_center_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8 COMMENT='线路表';

/*Data for the table `idcsmart_module_mf_cloud_line` */


/*Table structure for table `idcsmart_module_mf_cloud_option` */

DROP TABLE IF EXISTS `idcsmart_module_mf_cloud_option`;

CREATE TABLE `idcsmart_module_mf_cloud_option` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT '商品ID',
  `rel_type` tinyint(7) NOT NULL DEFAULT '0' COMMENT '0=CPU配置\r\n1=内存配置\r\n2=线路带宽计费\r\n3=线路流量计费\r\n4=线路防护配置\r\n5=线路附加IP配置\r\n6=系统盘配置\r\n7=数据盘配置',
  `rel_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联ID',
  `type` varchar(30) NOT NULL DEFAULT '' COMMENT '计费方式(radio=单选，step=阶梯,total=总量)',
  `value` int(10) NOT NULL DEFAULT '0' COMMENT '单选值',
  `min_value` int(10) NOT NULL DEFAULT '0' COMMENT '最小值',
  `max_value` int(10) NOT NULL DEFAULT '0' COMMENT '最大值',
  `step` int(10) NOT NULL DEFAULT '1' COMMENT '步长',
  `other_config` text NOT NULL COMMENT '其他配置,json存储',
  `create_time` int(11) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `prr` (`product_id`,`rel_type`,`rel_id`),
  KEY `value` (`value`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8 COMMENT='通用配置表';

/*Data for the table `idcsmart_module_mf_cloud_option` */


/*Table structure for table `idcsmart_module_mf_cloud_price` */

DROP TABLE IF EXISTS `idcsmart_module_mf_cloud_price`;

CREATE TABLE `idcsmart_module_mf_cloud_price` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `product_id` int(11) NOT NULL COMMENT '商品ID',
  `rel_id` int(11) NOT NULL DEFAULT '0' COMMENT '配置ID',
  `duration_id` int(11) NOT NULL DEFAULT '0' COMMENT '周期ID',
  `price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '价格',
  `rel_type` tinyint(4) NOT NULL DEFAULT '0' COMMENT '关联表:0=option,1=recommend_config',
  PRIMARY KEY (`id`),
  KEY `duration_id` (`duration_id`),
  KEY `prr` (`product_id`,`rel_id`,`rel_type`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8 COMMENT='配置价格表';

/*Data for the table `idcsmart_module_mf_cloud_price` */


/*Table structure for table `idcsmart_module_mf_cloud_recommend_config` */

DROP TABLE IF EXISTS `idcsmart_module_mf_cloud_recommend_config`;

CREATE TABLE `idcsmart_module_mf_cloud_recommend_config` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT '商品ID',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT '名称',
  `description` text NOT NULL COMMENT '描述',
  `order` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `data_center_id` int(11) NOT NULL DEFAULT '0' COMMENT '数据中心ID',
  `cpu` int(11) NOT NULL DEFAULT '0' COMMENT 'CPU',
  `memory` int(11) NOT NULL DEFAULT '0' COMMENT '内存',
  `system_disk_size` int(11) NOT NULL DEFAULT '0' COMMENT '系统盘大小',
  `data_disk_size` int(11) NOT NULL DEFAULT '0' COMMENT '数据盘大小',
  `bw` int(11) NOT NULL DEFAULT '0' COMMENT '带宽',
  `peak_defence` int(11) NOT NULL DEFAULT '0' COMMENT '防御峰值',
  `system_disk_type` varchar(255) NOT NULL DEFAULT '' COMMENT '系统盘类型',
  `data_disk_type` varchar(255) NOT NULL DEFAULT '' COMMENT '数据盘类型',
  `flow` int(11) NOT NULL DEFAULT '0' COMMENT '流量',
  `line_id` int(11) NOT NULL DEFAULT '0' COMMENT '线路ID',
  `create_time` int(11) NOT NULL DEFAULT '0',
  `ip_num` int(11) NOT NULL DEFAULT '1' COMMENT 'IP数量',
  `upgrade_range` tinyint(3) NOT NULL DEFAULT '0' COMMENT '0=不可升降级,1=全部,2=自定义',
  `hidden` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否隐藏(0=否,1=是)',
  `gpu_num` int(11) NOT NULL DEFAULT '0' COMMENT 'GPU数量',
  `ipv6_num` int(11) unsigned NOT NULL DEFAULT '0' COMMENT 'IPv6数量',
  PRIMARY KEY (`id`),
  KEY `product_id` (`product_id`),
  KEY `order` (`order`),
  KEY `data_center_id` (`data_center_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8 COMMENT='推荐配置表';

/*Data for the table `idcsmart_module_mf_cloud_recommend_config` */


/*Table structure for table `idcsmart_module_mf_cloud_recommend_config_upgrade_range` */

DROP TABLE IF EXISTS `idcsmart_module_mf_cloud_recommend_config_upgrade_range`;

CREATE TABLE `idcsmart_module_mf_cloud_recommend_config_upgrade_range` (
  `recommend_config_id` int(11) NOT NULL DEFAULT '0' COMMENT '套餐ID',
  `rel_recommend_config_id` int(11) NOT NULL DEFAULT '0' COMMENT '可升降级套餐ID',
  KEY `recommend_config_id` (`recommend_config_id`),
  KEY `rel_recommend_config_id` (`rel_recommend_config_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

/*Data for the table `idcsmart_module_mf_cloud_recommend_config_upgrade_range` */

/*Table structure for table `idcsmart_module_mf_cloud_resource_package` */

DROP TABLE IF EXISTS `idcsmart_module_mf_cloud_resource_package`;

CREATE TABLE `idcsmart_module_mf_cloud_resource_package` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT '商品ID',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT '资源包名称',
  `rid` int(11) NOT NULL DEFAULT '0' COMMENT '魔方云资源包ID',
  PRIMARY KEY (`id`),
  KEY `product_id` (`product_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

/*Data for the table `idcsmart_module_mf_cloud_resource_package` */

/*Table structure for table `idcsmart_module_mf_cloud_vpc_network` */

DROP TABLE IF EXISTS `idcsmart_module_mf_cloud_vpc_network`;

CREATE TABLE `idcsmart_module_mf_cloud_vpc_network` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT '商品ID',
  `data_center_id` int(11) NOT NULL DEFAULT '0' COMMENT '数据中心ID',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT '名称',
  `client_id` int(11) NOT NULL DEFAULT '0' COMMENT '用户ID',
  `ips` varchar(50) NOT NULL DEFAULT '' COMMENT 'VPC网段',
  `rel_id` int(11) NOT NULL DEFAULT '0' COMMENT '魔方云VPCID',
  `vpc_name` varchar(255) NOT NULL DEFAULT '',
  `downstream_client_id` int(11) NOT NULL DEFAULT '0',
  `create_time` int(11) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `product_id` (`product_id`),
  KEY `data_center_id` (`data_center_id`),
  KEY `downstream_client_id` (`downstream_client_id`),
  KEY `client_id` (`client_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

/*Data for the table `idcsmart_module_mf_cloud_vpc_network` */

/*Table structure for table `idcsmart_module_mf_dcim_config` */

DROP TABLE IF EXISTS `idcsmart_module_mf_dcim_config`;

CREATE TABLE `idcsmart_module_mf_dcim_config` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `product_id` int(11) NOT NULL DEFAULT '0',
  `rand_ssh_port` tinyint(3) NOT NULL DEFAULT '0' COMMENT '随机SSH端口(0=关闭,1=开启)',
  `reinstall_sms_verify` tinyint(3) NOT NULL DEFAULT '0' COMMENT '重装短信验证(0=关闭,1=开启)',
  `reset_password_sms_verify` tinyint(3) NOT NULL DEFAULT '0' COMMENT '重置密码短信验证(0=关闭,1=开启)',
  `manual_resource` tinyint(3) NOT NULL DEFAULT '0' COMMENT '手动资源(0=关闭,1=开启)',
  `level_discount_memory_order` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '内存是否用等级优惠订购(0=关闭,1=开启)',
  `level_discount_memory_upgrade` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '内存是否用等级优惠升降级(0=关闭,1=开启)',
  `level_discount_disk_order` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '硬盘是否用等级优惠订购(0=关闭,1=开启)',
  `level_discount_disk_upgrade` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '硬盘是否用等级优惠升降级(0=关闭,1=开启)',
  `level_discount_bw_upgrade` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '带宽是否用等级优惠升降级(0=关闭,1=开启)',
  `level_discount_ip_num_upgrade` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT 'IP是否用等级优惠升降级(0=关闭,1=开启)',
  `optional_host_auto_create` tinyint(1) NOT NULL DEFAULT '0' COMMENT '选配机器是否自动开通(0=关闭,1=开启)',
  `level_discount_gpu_order` tinyint(1) NOT NULL DEFAULT '1' COMMENT '显卡是否应用等级优惠订购(0=关闭,1=开启)',
  `level_discount_gpu_upgrade` tinyint(1) NOT NULL DEFAULT '1' COMMENT '显卡是否应用等级优惠升降级(0=关闭,1=开启)',
  PRIMARY KEY (`id`),
  KEY `product_id` (`product_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8;

/*Data for the table `idcsmart_module_mf_dcim_config` */


/*Table structure for table `idcsmart_module_mf_dcim_config_limit` */

DROP TABLE IF EXISTS `idcsmart_module_mf_dcim_config_limit`;

CREATE TABLE `idcsmart_module_mf_dcim_config_limit` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT '商品ID',
  `data_center_id` int(11) NOT NULL DEFAULT '0' COMMENT '数据中心ID',
  `line_id` int(11) NOT NULL DEFAULT '0' COMMENT '线路ID',
  `model_config_id` text NOT NULL COMMENT '配置型号ID',
  `min_bw` varchar(20) NOT NULL DEFAULT '' COMMENT '最小带宽',
  `max_bw` varchar(20) NOT NULL DEFAULT '' COMMENT '最大带宽',
  `min_flow` varchar(20) NOT NULL DEFAULT '' COMMENT '流量',
  `max_flow` varchar(20) NOT NULL DEFAULT '',
  `create_time` int(11) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `product_id` (`product_id`) USING BTREE,
  KEY `data_center_id` (`data_center_id`),
  KEY `line_id` (`line_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='配置限制表';

/*Data for the table `idcsmart_module_mf_dcim_config_limit` */

/*Table structure for table `idcsmart_module_mf_dcim_data_center` */

DROP TABLE IF EXISTS `idcsmart_module_mf_dcim_data_center`;

CREATE TABLE `idcsmart_module_mf_dcim_data_center` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT '商品ID',
  `country_id` int(11) NOT NULL DEFAULT '0' COMMENT '国家ID',
  `city` varchar(255) NOT NULL DEFAULT '' COMMENT '城市',
  `area` varchar(255) NOT NULL DEFAULT '' COMMENT '区域',
  `order` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `create_time` int(11) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `product_id` (`product_id`),
  KEY `country_id` (`country_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8 COMMENT='数据中心表';

/*Data for the table `idcsmart_module_mf_dcim_data_center` */


/*Table structure for table `idcsmart_module_mf_dcim_duration` */

DROP TABLE IF EXISTS `idcsmart_module_mf_dcim_duration`;

CREATE TABLE `idcsmart_module_mf_dcim_duration` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT '商品ID',
  `name` varchar(30) NOT NULL DEFAULT '' COMMENT '周期名称',
  `num` int(11) NOT NULL DEFAULT '0' COMMENT '周期时常',
  `unit` varchar(20) NOT NULL DEFAULT '' COMMENT '周期单位(hour=小时,day=天,month=自然月)',
  `create_time` int(11) NOT NULL DEFAULT '0',
  `price_factor` float(4,2) NOT NULL DEFAULT '1.00' COMMENT '价格系数',
  `price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '周期价格',
  PRIMARY KEY (`id`),
  KEY `product_id` (`product_id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8 COMMENT='周期表';

