/*Table structure for table `idcsmart_module_mf_dcim_line` */

DROP TABLE IF EXISTS `idcsmart_module_mf_dcim_line`;

CREATE TABLE `idcsmart_module_mf_dcim_line` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `data_center_id` int(11) NOT NULL DEFAULT '0' COMMENT '数据中心ID',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT '线路名称',
  `bill_type` varchar(20) NOT NULL DEFAULT '' COMMENT 'bw=带宽计费,flow=流量计费',
  `bw_ip_group` varchar(10) NOT NULL DEFAULT '' COMMENT '带宽IP分组',
  `defence_enable` tinyint(3) NOT NULL DEFAULT '0' COMMENT '是否启用防护',
  `defence_ip_group` varchar(10) NOT NULL DEFAULT '' COMMENT '防护IP分组',
  `create_time` int(11) NOT NULL DEFAULT '0',
  `order` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  PRIMARY KEY (`id`),
  KEY `data_center_id` (`data_center_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8 COMMENT='线路表';

/*Data for the table `idcsmart_module_mf_dcim_line` */


/*Table structure for table `idcsmart_module_mf_dcim_model_config` */

DROP TABLE IF EXISTS `idcsmart_module_mf_dcim_model_config`;

CREATE TABLE `idcsmart_module_mf_dcim_model_config` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT '商品ID',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT '名称',
  `group_id` int(11) NOT NULL DEFAULT '0' COMMENT 'DCIM分组ID',
  `cpu` varchar(255) NOT NULL DEFAULT '' COMMENT '处理器',
  `cpu_param` varchar(255) NOT NULL DEFAULT '' COMMENT '处理器参数',
  `memory` varchar(255) NOT NULL DEFAULT '' COMMENT '内存',
  `disk` varchar(255) NOT NULL DEFAULT '' COMMENT '硬盘',
  `create_time` int(11) NOT NULL DEFAULT '0',
  `update_time` int(11) DEFAULT '0',
  `order` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `hidden` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否隐藏(0=隐藏,1=显示)',
  `support_optional` tinyint(1) NOT NULL DEFAULT '0' COMMENT '支持选配(0=不支持,1=支持)',
  `leave_memory` int(11) NOT NULL DEFAULT '0' COMMENT '剩余容量',
  `max_memory_num` int(11) NOT NULL DEFAULT '0' COMMENT '可增加内存条数',
  `max_disk_num` int(11) NOT NULL DEFAULT '0' COMMENT '可增加硬盘数量',
  `gpu` varchar(255) NOT NULL DEFAULT '' COMMENT '显卡',
  `max_gpu_num` int(11) NOT NULL DEFAULT '0' COMMENT '可增加显卡数量',
  `optional_only_for_upgrade` tinyint(1) NOT NULL DEFAULT '0' COMMENT '增值仅用于升降级(0=关闭,1=开启)',
  PRIMARY KEY (`id`),
  KEY `product_id` (`product_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8 COMMENT='型号配置';

/*Data for the table `idcsmart_module_mf_dcim_model_config` */


/*Table structure for table `idcsmart_module_mf_dcim_model_config_option_link` */

DROP TABLE IF EXISTS `idcsmart_module_mf_dcim_model_config_option_link`;

CREATE TABLE `idcsmart_module_mf_dcim_model_config_option_link` (
  `model_config_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT 'dcim型号配置id',
  `option_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '可选配optionID',
  `option_rel_type` tinyint(7) unsigned NOT NULL DEFAULT '0' COMMENT 'option表的rel_type',
  KEY `idx_model_config_id` (`model_config_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='型号配置可选配置表';

/*Data for the table `idcsmart_module_mf_dcim_model_config_option_link` */

/*Table structure for table `idcsmart_module_mf_dcim_option` */

DROP TABLE IF EXISTS `idcsmart_module_mf_dcim_option`;

CREATE TABLE `idcsmart_module_mf_dcim_option` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT '商品ID',
  `rel_type` tinyint(7) NOT NULL DEFAULT '0' COMMENT '2=线路带宽计费\r\n3=线路流量计费\r\n4=线路防护配置\r\n5=线路附加IP配置',
  `rel_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联ID',
  `type` varchar(30) NOT NULL DEFAULT '' COMMENT '计费方式(radio=单选，step=阶梯,total=总量)',
  `value` varchar(255) NOT NULL DEFAULT '0' COMMENT '单选值',
  `min_value` int(10) NOT NULL DEFAULT '0' COMMENT '最小值',
  `max_value` int(10) NOT NULL DEFAULT '0' COMMENT '最大值',
  `step` int(10) NOT NULL DEFAULT '1' COMMENT '步长',
  `other_config` text NOT NULL COMMENT '其他配置,json存储',
  `create_time` int(11) NOT NULL DEFAULT '0',
  `order` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '排序',
  `value_show` varchar(255) NOT NULL DEFAULT '' COMMENT '实际显示',
  PRIMARY KEY (`id`),
  KEY `prr` (`product_id`,`rel_type`,`rel_id`),
  KEY `value` (`value`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8 COMMENT='通用配置表';

/*Data for the table `idcsmart_module_mf_dcim_option` */


/*Table structure for table `idcsmart_module_mf_dcim_package` */

DROP TABLE IF EXISTS `idcsmart_module_mf_dcim_package`;

CREATE TABLE `idcsmart_module_mf_dcim_package` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `product_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '商品ID',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT '名称',
  `group_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT 'DCIM分组ID',
  `cpu_option_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '处理器关联optionID',
  `cpu_num` int(11) unsigned NOT NULL DEFAULT '1' COMMENT 'CPU数量',
  `mem_option_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '内存关联optionID',
  `mem_num` tinyint(7) unsigned NOT NULL DEFAULT '1' COMMENT '内存数量',
  `disk_option_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '硬盘关联optionID',
  `disk_num` tinyint(7) unsigned NOT NULL DEFAULT '1' COMMENT '硬盘数量',
  `bw` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '带宽',
  `ip_num` int(11) unsigned NOT NULL DEFAULT '0' COMMENT 'IP数量',
  `description` varchar(1000) NOT NULL DEFAULT '' COMMENT '描述',
  `mem_max` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '内存最大容量',
  `mem_max_num` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '内存最大数量',
  `disk_max_num` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '硬盘最大数量',
  `order` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '排序',
  `hidden` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '是否隐藏(0=否,1=是)',
  `create_time` int(11) unsigned NOT NULL DEFAULT '0',
  `update_time` int(11) unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_product_id` (`product_id`) USING BTREE,
  KEY `idx_cpu_option_id` (`cpu_option_id`) USING BTREE,
  KEY `idx_mem_option_id` (`mem_option_id`) USING BTREE,
  KEY `idx_disk_option_id` (`disk_option_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='套餐表';

/*Data for the table `idcsmart_module_mf_dcim_package` */

/*Table structure for table `idcsmart_module_mf_dcim_package_option_link` */

DROP TABLE IF EXISTS `idcsmart_module_mf_dcim_package_option_link`;

CREATE TABLE `idcsmart_module_mf_dcim_package_option_link` (
  `package_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT 'dcim套餐id',
  `option_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '可选配optionID',
  `option_rel_type` tinyint(7) unsigned NOT NULL DEFAULT '0' COMMENT 'option表的rel_type',
  KEY `idx_package_id` (`package_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='套餐可选配置表';

/*Data for the table `idcsmart_module_mf_dcim_package_option_link` */

/*Table structure for table `idcsmart_module_mf_dcim_price` */

DROP TABLE IF EXISTS `idcsmart_module_mf_dcim_price`;

CREATE TABLE `idcsmart_module_mf_dcim_price` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `product_id` int(11) NOT NULL COMMENT '商品ID',
  `rel_type` varchar(30) NOT NULL DEFAULT '' COMMENT '表类型(model_config=型号配置,option=通用配置)',
  `rel_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联ID',
  `duration_id` int(11) NOT NULL DEFAULT '0' COMMENT '周期ID',
  `price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '价格',
  PRIMARY KEY (`id`),
  KEY `product_id` (`product_id`),
  KEY `rr` (`rel_type`,`rel_id`),
  KEY `duration_id` (`duration_id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8 COMMENT='配置价格表';

/*Data for the table `idcsmart_module_mf_dcim_price` */


/*Table structure for table `idcsmart_nav` */

DROP TABLE IF EXISTS `idcsmart_nav`;

CREATE TABLE `idcsmart_nav` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '默认导航表',
  `type` varchar(20) NOT NULL DEFAULT '' COMMENT '类型admin后台home前台',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT '名称',
  `url` varchar(255) NOT NULL DEFAULT '' COMMENT '地址',
  `icon` varchar(255) NOT NULL DEFAULT '' COMMENT '图标',
  `parent_id` int(11) NOT NULL DEFAULT '0' COMMENT '上级id',
  `order` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `module` varchar(20) NOT NULL DEFAULT '' COMMENT '插件模块路径,如:gateway支付接口/sms短信接口/mail邮件接口/addon插件',
  `plugin` varchar(100) NOT NULL DEFAULT '' COMMENT '插件',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `parent_id` (`parent_id`)
) ENGINE=InnoDB AUTO_INCREMENT=58 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=COMPACT COMMENT='默认导航表';

/*Data for the table `idcsmart_nav` */


/*Table structure for table `idcsmart_notice_setting` */

DROP TABLE IF EXISTS `idcsmart_notice_setting`;

CREATE TABLE `idcsmart_notice_setting` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT '发送管理',
  `name` varchar(100) NOT NULL COMMENT '动作标识名称',
  `name_lang` varchar(100) NOT NULL DEFAULT '' COMMENT '动作名称',
  `sms_global_name` varchar(50) NOT NULL DEFAULT '' COMMENT '短信国际接口名称',
  `sms_global_template` int(10) NOT NULL DEFAULT '0' COMMENT '短信国际接口模板id',
  `sms_name` varchar(50) NOT NULL DEFAULT '' COMMENT '短信国内接口名称',
  `sms_template` int(10) NOT NULL DEFAULT '0' COMMENT '短信国内接口模板id',
  `sms_enable` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0禁用,1启用',
  `email_name` varchar(50) NOT NULL DEFAULT '' COMMENT '邮件接口名称',
  `email_template` int(10) NOT NULL DEFAULT '0' COMMENT '邮件接口模板id',
  `email_enable` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0禁用,1启用',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=37 DEFAULT CHARSET=utf8mb4;

/*Data for the table `idcsmart_notice_setting` */


/*Table structure for table `idcsmart_oauth` */

DROP TABLE IF EXISTS `idcsmart_oauth`;

CREATE TABLE `idcsmart_oauth` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `type` varchar(32) NOT NULL DEFAULT '' COMMENT '三方插件标识',
  `client_id` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `openid` varchar(128) NOT NULL DEFAULT '' COMMENT '三方登录标识',
  `oauth` text NOT NULL COMMENT '三方信息',
  `create_time` int(10) unsigned NOT NULL DEFAULT '0',
  `update_time` int(10) unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_client_id` (`client_id`),
  KEY `idx_openid` (`openid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='三方登录信息表';

/*Data for the table `idcsmart_oauth` */

/*Table structure for table `idcsmart_order` */

DROP TABLE IF EXISTS `idcsmart_order`;

CREATE TABLE `idcsmart_order` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '订单ID',
  `client_id` int(11) NOT NULL DEFAULT '0' COMMENT '用户ID',
  `type` varchar(100) NOT NULL DEFAULT 'new' COMMENT '类型new新订单renew续费订单upgrade升降级订单artificial人工订单',
  `status` varchar(20) NOT NULL DEFAULT 'Unpaid' COMMENT '状态Paid已付款Unpaid未付款',
  `amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '金额',
  `credit` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '余额',
  `amount_unpaid` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '未付款金额',
  `upgrade_refund` tinyint(1) NOT NULL DEFAULT '1' COMMENT '升降级是否退款0否1是',
  `gateway` varchar(100) NOT NULL DEFAULT '' COMMENT '支付方式',
  `gateway_name` varchar(100) NOT NULL DEFAULT '' COMMENT '支付方式名称',
  `notes` varchar(1000) NOT NULL DEFAULT '' COMMENT '备注',
  `pay_time` int(11) NOT NULL DEFAULT '0' COMMENT '支付时间',
  `due_time` int(11) NOT NULL DEFAULT '0' COMMENT '到期时间',
  `create_time` int(11) NOT NULL DEFAULT '0' COMMENT '创建时间',
  `update_time` int(11) NOT NULL DEFAULT '0' COMMENT '更新时间',
  `refund_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '退款金额',
  `admin_id` int(11) NOT NULL DEFAULT '0' COMMENT '管理员ID',
  `is_lock` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '是否锁定(0=否,1=是)',
  `recycle_time` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '放入回收站时间',
  `will_delete_time` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '彻底删除时间',
  `is_recycle` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '是否在回收站(0=否,1=是)',
  `return_url` varchar(255) NOT NULL DEFAULT '' COMMENT '同步回调跳转地址',
  PRIMARY KEY (`id`),
  KEY `client_id` (`client_id`),
  KEY `type` (`type`),
  KEY `status` (`status`),
  KEY `amount` (`amount`),
  KEY `pay_time` (`pay_time`),
  KEY `admin_id` (`admin_id`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=COMPACT COMMENT='订单表';

/*Data for the table `idcsmart_order` */


/*Table structure for table `idcsmart_order_item` */

DROP TABLE IF EXISTS `idcsmart_order_item`;

CREATE TABLE `idcsmart_order_item` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '订单子项ID',
  `order_id` int(11) NOT NULL DEFAULT '0' COMMENT '订单ID',
  `client_id` int(11) NOT NULL DEFAULT '0' COMMENT '用户ID',
  `host_id` int(11) NOT NULL DEFAULT '0' COMMENT '产品ID',
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT '商品ID',
  `type` varchar(100) NOT NULL DEFAULT '' COMMENT '关联类型',
  `rel_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联ID',
  `description` varchar(1000) NOT NULL DEFAULT '' COMMENT '描述',
  `amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '金额',
  `gateway` varchar(100) NOT NULL DEFAULT '' COMMENT '支付方式',
  `gateway_name` varchar(100) NOT NULL DEFAULT '' COMMENT '支付方式名称',
  `notes` varchar(1000) NOT NULL DEFAULT '' COMMENT '备注',
  `create_time` int(11) NOT NULL DEFAULT '0' COMMENT '创建时间',
  `update_time` int(11) NOT NULL DEFAULT '0' COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `order_id` (`order_id`),
  KEY `client_id` (`client_id`),
  KEY `rel_id` (`type`,`rel_id`),
  KEY `host_id` (`host_id`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=COMPACT COMMENT='订单子项表';

/*Data for the table `idcsmart_order_item` */


/*Table structure for table `idcsmart_order_tmp` */

DROP TABLE IF EXISTS `idcsmart_order_tmp`;

CREATE TABLE `idcsmart_order_tmp` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL DEFAULT '0' COMMENT '订单ID',
  `tmp_order_id` varchar(50) NOT NULL DEFAULT '' COMMENT '21-22位临时订单ID,传入三方接口',
  `tmp_order_id2` varchar(30) NOT NULL DEFAULT '' COMMENT '18位临时订单ID规则2,传入三方接口',
  `tmp_order_id3` varchar(20) NOT NULL DEFAULT '' COMMENT '10位临时订单ID规则3,传入三方接口',
  `create_time` int(11) NOT NULL DEFAULT '0' COMMENT '创建时间,72小时定时任务清除',
  PRIMARY KEY (`id`),
  KEY `order_id` (`order_id`),
  KEY `tmp_order_id` (`tmp_order_id`),
  KEY `tmp_order_id2` (`tmp_order_id2`),
  KEY `tmp_order_id3` (`tmp_order_id3`)
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=utf8mb4;

/*Data for the table `idcsmart_order_tmp` */


/*Table structure for table `idcsmart_partner` */

DROP TABLE IF EXISTS `idcsmart_partner`;

CREATE TABLE `idcsmart_partner` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '合作伙伴ID',
  `name` varchar(100) NOT NULL DEFAULT '' COMMENT '名称',
  `img` varchar(255) NOT NULL DEFAULT '' COMMENT '图片地址',
  `description` text NOT NULL COMMENT '描述',
  `create_time` int(11) NOT NULL DEFAULT '0' COMMENT '创建时间',
  `update_time` int(11) NOT NULL DEFAULT '0' COMMENT '更新时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='合作伙伴';

/*Data for the table `idcsmart_partner` */

/*Table structure for table `idcsmart_physical_server_area` */

DROP TABLE IF EXISTS `idcsmart_physical_server_area`;

CREATE TABLE `idcsmart_physical_server_area` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '区域ID',
  `first_area` varchar(100) NOT NULL DEFAULT '' COMMENT '一级区域',
  `second_area` varchar(100) NOT NULL DEFAULT '' COMMENT '二级区域',
  `create_time` int(11) NOT NULL DEFAULT '0' COMMENT '创建时间',
  `update_time` int(11) NOT NULL DEFAULT '0' COMMENT '更新时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='物理服务器区域表';

/*Data for the table `idcsmart_physical_server_area` */

/*Table structure for table `idcsmart_physical_server_banner` */

DROP TABLE IF EXISTS `idcsmart_physical_server_banner`;

CREATE TABLE `idcsmart_physical_server_banner` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '轮播图ID',
  `img` varchar(255) NOT NULL DEFAULT '' COMMENT '图片',
  `url` varchar(255) NOT NULL DEFAULT '' COMMENT '跳转链接',
  `start_time` int(11) NOT NULL DEFAULT '0' COMMENT '开始时间',
  `end_time` int(11) NOT NULL DEFAULT '0' COMMENT '结束时间',
  `show` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否展示0否1是',
  `notes` varchar(1000) NOT NULL DEFAULT '' COMMENT '备注',
  `order` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `create_time` int(11) NOT NULL DEFAULT '0' COMMENT '创建时间',
  `update_time` int(11) NOT NULL DEFAULT '0' COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `show` (`show`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='物理服务器轮播图表';

/*Data for the table `idcsmart_physical_server_banner` */

/*Table structure for table `idcsmart_physical_server_discount` */

DROP TABLE IF EXISTS `idcsmart_physical_server_discount`;

CREATE TABLE `idcsmart_physical_server_discount` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '优惠ID',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT '标题',
  `description` varchar(1000) NOT NULL DEFAULT '' COMMENT '描述',
  `url` varchar(255) NOT NULL DEFAULT '' COMMENT '跳转链接',
  `create_time` int(11) NOT NULL DEFAULT '0' COMMENT '创建时间',
  `update_time` int(11) NOT NULL DEFAULT '0' COMMENT '更新时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='物理服务器优惠表';

/*Data for the table `idcsmart_physical_server_discount` */

/*Table structure for table `idcsmart_physical_server_product` */

DROP TABLE IF EXISTS `idcsmart_physical_server_product`;

CREATE TABLE `idcsmart_physical_server_product` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '商品ID',
  `area_id` int(11) NOT NULL DEFAULT '0' COMMENT '区域ID',
  `title` varchar(50) NOT NULL DEFAULT '' COMMENT '标题',
  `description` varchar(100) NOT NULL DEFAULT '' COMMENT '描述',
  `cpu` text NOT NULL COMMENT '处理器',
  `memory` text NOT NULL COMMENT '内存',
  `disk` text NOT NULL COMMENT '硬盘',
  `ip_num` text NOT NULL COMMENT 'IP数量',
  `bandwidth` text NOT NULL COMMENT '带宽',
  `duration` text NOT NULL COMMENT '时长',
  `tag` text NOT NULL COMMENT '标签',
  `original_price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '原价',
  `original_price_unit` varchar(10) NOT NULL DEFAULT '' COMMENT '原价单位,month月year年',
  `selling_price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '售价',
  `selling_price_unit` varchar(10) NOT NULL DEFAULT '' COMMENT '售价单位,month月year年',
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联商品ID',
  `create_time` int(11) NOT NULL DEFAULT '0' COMMENT '创建时间',
  `update_time` int(11) NOT NULL DEFAULT '0' COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `area_id` (`area_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='物理服务器商品表';

/*Data for the table `idcsmart_physical_server_product` */

/*Table structure for table `idcsmart_plugin` */

DROP TABLE IF EXISTS `idcsmart_plugin`;

CREATE TABLE `idcsmart_plugin` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '自增id',
  `status` tinyint(1) unsigned NOT NULL DEFAULT '1' COMMENT '状态;1:开启;0:禁用',
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT '插件标识名,英文字母(唯一)',
  `title` varchar(50) NOT NULL DEFAULT '' COMMENT '插件名称',
  `url` text COMMENT '图标地址',
  `author` varchar(255) NOT NULL DEFAULT '' COMMENT '作者',
  `author_url` text COMMENT '作者链接',
  `version` varchar(20) NOT NULL DEFAULT '1.0' COMMENT '插件版本号',
  `description` text COMMENT '插件描述',
  `config` text COMMENT '插件配置',
  `module` varchar(25) NOT NULL DEFAULT '' COMMENT '插件模块路径,如:gateway支付接口/sms短信接口/mail邮件接口/addon插件',
  `order` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `help_url` varchar(1000) NOT NULL DEFAULT '' COMMENT '帮助文档',
  `create_time` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '插件安装时间',
  `update_time` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '插件更新时间',
  `hook_order` int(11) NOT NULL DEFAULT '0' COMMENT 'hook排序',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `name` (`name`),
  KEY `status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=35 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=COMPACT COMMENT='插件表';

/*Data for the table `idcsmart_plugin` */


/*Table structure for table `idcsmart_plugin_hook` */

DROP TABLE IF EXISTS `idcsmart_plugin_hook`;

CREATE TABLE `idcsmart_plugin_hook` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT '钩子名',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态(0:禁用,1:启用)',
  `plugin` varchar(50) NOT NULL DEFAULT '' COMMENT '插件标识名',
  `module` varchar(25) NOT NULL DEFAULT 'addon' COMMENT '插件所属模块',
  `order` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `plugin` (`plugin`),
  KEY `module` (`plugin`)
) ENGINE=InnoDB AUTO_INCREMENT=43 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=COMPACT COMMENT='插件钩子表';

/*Data for the table `idcsmart_plugin_hook` */


/*Table structure for table `idcsmart_price` */

DROP TABLE IF EXISTS `idcsmart_price`;

CREATE TABLE `idcsmart_price` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '模块周期价格表ID',
  `module` varchar(100) NOT NULL DEFAULT '' COMMENT '模块名称',
  `config_option_sub_id` int(11) NOT NULL DEFAULT '0' COMMENT '自定义配置子项ID',
  `name` varchar(100) NOT NULL DEFAULT '' COMMENT '标识',
  `billing_cycle` int(11) NOT NULL DEFAULT '0' COMMENT '计费周期,按秒存储',
  `price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '价格',
  `create_time` int(11) NOT NULL DEFAULT '0' COMMENT '创建时间',
  `update_time` int(11) NOT NULL DEFAULT '0' COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `module` (`module`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='模块周期价格表';

/*Data for the table `idcsmart_price` */

/*Table structure for table `idcsmart_product` */

DROP TABLE IF EXISTS `idcsmart_product`;

CREATE TABLE `idcsmart_product` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '商品表ID',
  `name` varchar(100) NOT NULL DEFAULT '' COMMENT '商品名称',
  `product_group_id` int(11) NOT NULL DEFAULT '0' COMMENT '所属商品组ID',
  `description` text COMMENT '商品描述',
  `hidden` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0显示默认，1隐藏',
  `stock_control` tinyint(1) NOT NULL DEFAULT '0' COMMENT '库存控制(1:启用)默认0',
  `qty` int(11) NOT NULL DEFAULT '0' COMMENT '库存数量(与stock_control有关)',
  `pay_type` varchar(255) NOT NULL DEFAULT '' COMMENT '付款类型(免费free，一次onetime，周期先付recurring_prepayment,周期后付recurring_postpaid',
  `auto_setup` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否自动开通:1是默认,0否',
  `type` varchar(50) NOT NULL DEFAULT 'server_group' COMMENT '关联类型:server,server_group',
  `rel_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联ID',
  `order` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `creating_notice_sms` tinyint(1) NOT NULL DEFAULT '1' COMMENT '开通中短信通知是否开启:1开启默认,0关闭',
  `creating_notice_sms_api` int(11) NOT NULL DEFAULT '0' COMMENT '开通中短信通知接口,默认0',
  `creating_notice_sms_api_template` int(11) NOT NULL DEFAULT '0' COMMENT '开通中短信通知接口模板,默认0',
  `created_notice_sms` tinyint(1) NOT NULL DEFAULT '1' COMMENT '已开通短信通知是否开启:1开启默认,0关闭',
  `created_notice_sms_api` int(11) NOT NULL DEFAULT '0' COMMENT '已开通短信通知接口,默认0',
  `created_notice_sms_api_template` int(11) NOT NULL DEFAULT '0' COMMENT '已开通短信通知接口模板,默认0',
  `creating_notice_mail` tinyint(1) NOT NULL DEFAULT '1' COMMENT '开通中邮件通知是否开启:1开启默认,0关闭',
  `creating_notice_mail_api` int(11) NOT NULL DEFAULT '0' COMMENT '开通中邮件通知接口',
  `creating_notice_mail_template` int(11) NOT NULL DEFAULT '0' COMMENT '开通中邮件通知模板,默认0',
  `created_notice_mail` tinyint(1) NOT NULL DEFAULT '1' COMMENT '已开通邮件通知是否开启:1开启默认,0关闭',
  `created_notice_mail_api` int(11) NOT NULL DEFAULT '0' COMMENT '已开通邮件通知接口',
  `created_notice_mail_template` int(11) NOT NULL DEFAULT '0' COMMENT '已开通邮件通知模板,默认0',
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT '父级商品ID',
  `create_time` int(11) NOT NULL DEFAULT '0',
  `update_time` int(11) NOT NULL DEFAULT '0',
  `price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '显示价格,模块存进去',
  `cycle` varchar(50) NOT NULL DEFAULT '' COMMENT '显示周期,模块存进去',
  `agentable` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否可代理0否1是',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `product_group_id` (`product_group_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=COMPACT COMMENT='商品表';

/*Data for the table `idcsmart_product` */


/*Table structure for table `idcsmart_product_duration_ratio` */

DROP TABLE IF EXISTS `idcsmart_product_duration_ratio`;

CREATE TABLE `idcsmart_product_duration_ratio` (
  `duration_id` int(11) NOT NULL DEFAULT '0' COMMENT '周期ID',
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT '商品ID',
  `ratio` decimal(10,2) NOT NULL DEFAULT '1.00' COMMENT '比例',
  KEY `product_id` (`product_id`),
  KEY `duration_id` (`duration_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

/*Data for the table `idcsmart_product_duration_ratio` */

/*Table structure for table `idcsmart_product_group` */

DROP TABLE IF EXISTS `idcsmart_product_group`;

CREATE TABLE `idcsmart_product_group` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '商品组表ID',
  `name` varchar(100) NOT NULL DEFAULT '' COMMENT '商品组名称',
  `hidden` tinyint(1) NOT NULL DEFAULT '0' COMMENT '默认0，1：隐藏',
  `order` int(11) NOT NULL DEFAULT '0' COMMENT '排序，默认处理为添加自增长',
  `parent_id` int(10) NOT NULL DEFAULT '0' COMMENT '父分组ID,0表示此分组为一级分组',
  `create_time` int(11) NOT NULL DEFAULT '0' COMMENT '创建时间',
  `update_time` int(11) NOT NULL DEFAULT '0' COMMENT '修改时间',
  `type` varchar(25) NOT NULL DEFAULT '' COMMENT '类型',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `order` (`order`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=COMPACT COMMENT='商品组表';

/*Data for the table `idcsmart_product_group` */


/*Table structure for table `idcsmart_product_upgrade_product` */

DROP TABLE IF EXISTS `idcsmart_product_upgrade_product`;

CREATE TABLE `idcsmart_product_upgrade_product` (
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT '商品ID',
  `upgrade_product_id` int(11) NOT NULL DEFAULT '0' COMMENT '可升降级商品ID',
  KEY `product_id` (`product_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

/*Data for the table `idcsmart_product_upgrade_product` */

/*Table structure for table `idcsmart_refund_record` */

DROP TABLE IF EXISTS `idcsmart_refund_record`;

CREATE TABLE `idcsmart_refund_record` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '退款记录ID',
  `order_id` int(11) NOT NULL DEFAULT '0' COMMENT '订单ID',
  `client_id` int(11) NOT NULL DEFAULT '0' COMMENT '用户ID',
  `admin_id` int(11) NOT NULL DEFAULT '0' COMMENT '管理员ID',
  `type` varchar(20) NOT NULL DEFAULT 'credit' COMMENT '类型credit余额transaction交易流水',
  `transaction_id` int(11) NOT NULL DEFAULT '0' COMMENT '交易流水ID',
  `amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '退款金额',
  `create_time` int(11) NOT NULL DEFAULT '0' COMMENT '创建时间',
  `status` varchar(25) NOT NULL DEFAULT 'Pending' COMMENT '退款状态：Pending待审核，Reject已拒绝，Refunding退款中，Refunded已退款',
  `reason` varchar(255) NOT NULL DEFAULT '' COMMENT '拒绝原因',
  `refund_time` int(11) NOT NULL DEFAULT '0' COMMENT '退款时间',
  `gateway` varchar(255) NOT NULL DEFAULT '' COMMENT '退款方式',
  PRIMARY KEY (`id`),
  KEY `order_id` (`order_id`),
  KEY `type` (`type`),
  KEY `client_id` (`client_id`),
  KEY `admin_id` (`admin_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='退款记录表';

/*Data for the table `idcsmart_refund_record` */

/*Table structure for table `idcsmart_self_defined_field` */

DROP TABLE IF EXISTS `idcsmart_self_defined_field`;

CREATE TABLE `idcsmart_self_defined_field` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `type` varchar(20) NOT NULL DEFAULT '' COMMENT '类型(product=商品)',
  `relid` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '关联ID',
  `field_name` varchar(255) NOT NULL DEFAULT '' COMMENT '字段名称',
  `field_type` varchar(50) NOT NULL DEFAULT '' COMMENT '字段类型(text=文本框,link=链接,password=密码,dropdown=下拉,checkbox=勾选框,textarea=文本区)',
  `description` varchar(255) NOT NULL DEFAULT '' COMMENT '字段描述',
  `regexpr` varchar(255) NOT NULL DEFAULT '' COMMENT '正则验证规则',
  `field_option` varchar(255) NOT NULL DEFAULT '' COMMENT '下拉选项',
  `order` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '显示排序',
  `is_required` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '是否必填',
  `show_order_page` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '订购页可见(0=否,1=是)',
  `show_order_detail` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '订购详情可见(0=否,1=是)',
  `show_client_host_detail` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '前台产品内页可见(0=否1,=是)',
  `show_admin_host_detail` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '后台产品内页可见(0=否,1=是)',
  `show_client_host_list` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '前台列表可见(0=否,1=是)',
  `upstream_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '上游ID',
  `create_time` int(11) unsigned NOT NULL DEFAULT '0',
  `update_time` int(11) unsigned NOT NULL DEFAULT '0',
  `show_admin_host_list` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '后台产品列表可见(0=否,1=是)',
  PRIMARY KEY (`id`),
  KEY `idx_relid` (`relid`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='自定义字段表';

/*Data for the table `idcsmart_self_defined_field` */

/*Table structure for table `idcsmart_self_defined_field_value` */

DROP TABLE IF EXISTS `idcsmart_self_defined_field_value`;

CREATE TABLE `idcsmart_self_defined_field_value` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `self_defined_field_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '自定义字段ID',
  `relid` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '关联ID(产品ID)',
  `value` varchar(2000) NOT NULL DEFAULT '' COMMENT '值',
  `order_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '订单ID',
  `create_time` int(11) unsigned NOT NULL DEFAULT '0',
  `update_time` int(11) unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_self_defined_field_id` (`self_defined_field_id`) USING BTREE,
  KEY `idx_relid` (`relid`) USING BTREE,
  KEY `idx_order_id` (`order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='自定义字段值表';

/*Data for the table `idcsmart_self_defined_field_value` */

