insert  into `idcsmart_addon_idcsmart_announcement`(`id`,`addon_idcsmart_announcement_type_id`,`title`,`content`,`keywords`,`img`,`attachment`,`hidden`,`read`,`admin_id`,`create_time`,`update_time`) values (1,1,'Linux Polkit 权限提升漏洞预警','<!DOCTYPE html>\n<html>\n<head>\n</head>\n<body>\n<div data-version=\"3.0.0\" data-hash=\"d7d23fa8f75af898d4e5702249ad68e8\">&nbsp;</div>\n<div>\n<div class=\"document\">\n<div class=\"section\">\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">尊敬的主题云用户：</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">您好！国外安全研究团队披露在polkit的pkexec程序中存在一处权限提升漏洞。（CVE-2021-4034，亦称PwnKit）。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【漏洞评级】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">高风险</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【漏洞描述】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">CVE-2021-4034</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">攻击者可以通过在其默认配置中利用此漏洞实现用任何非特权用户获取易受攻击主机的完全root权限，目前漏洞POC/EXP已公开，风险较高。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【影响范围】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">该漏洞影响2009年5月至今所有polkit版本。由于polkit是系统的预装工具，所有存在polkit的linux系统均受影响。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【修复方案】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">目前RedHat、Ubuntu、Debian、SUSE等各大Linux厂商均已发布补丁版本修复了该漏洞，请受影响的用户升级到安全版本。</span></p>\n</div>\n</div>\n</div>\n</body>\n</html>','','','',0,0,1,1680240144,0);
insert  into `idcsmart_addon_idcsmart_announcement`(`id`,`addon_idcsmart_announcement_type_id`,`title`,`content`,`keywords`,`img`,`attachment`,`hidden`,`read`,`admin_id`,`create_time`,`update_time`) values (2,1,'Apache APISIX 远程代码执行漏洞预警','<!DOCTYPE html>\n<html>\n<head>\n</head>\n<body>\n<div data-version=\"3.0.0\" data-hash=\"c602be17153e25d0db9d0f388b924397\">&nbsp;</div>\n<div>\n<div class=\"document\">\n<div class=\"section\">\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">尊敬的主题云用户：</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">您好！ Apache APISIX官方发布安全通告，披露了 APISIX batch-requests 插件存在远程代码执行漏洞，漏洞编号CVE-2022-24112。可导致攻击者远程执行任意代码等危害。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【漏洞评级】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">高风险</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【漏洞描述】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">CVE-2022-24112</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">攻击者可以滥用batch-requests插件发送特制请求，并借此来绕过Admin API的IP限制，如绕过 IP 黑白名单限制。或者当用户使用 Apache APISIX 默认配置时（启用 Admin API ，使用默认 Admin Key 且没有额外分配管理端口），攻击者可以通过 batch-requests 插件调用 Admin API ，导致远程代码执行。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【影响范围】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">影响版本：</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">Apache APISIX &lt; 2.12.1</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">Apache APISIX &lt; 2.10.4 (LTS versions)</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【修复方案】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">官方已发布漏洞补丁及修复版本，请评估业务是否受影响后，酌情升级至安全版本。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">https://github.com/apache/apisix/releases/tag/2.12.1</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">https://github.com/apache/apisix/releases/tag/2.10.4</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">注：修复漏洞前请将资料备份，并进行充分测试。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【参考链接】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">https://apisix.apache.org/zh/blog/2022/02/11/cve-2022-24112/</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">https://nvd.nist.gov/vuln/detail/CVE-2022-24112</span></p>\n</div>\n</div>\n</div>\n</body>\n</html>','','','',0,0,1,1680240246,0);
insert  into `idcsmart_addon_idcsmart_announcement`(`id`,`addon_idcsmart_announcement_type_id`,`title`,`content`,`keywords`,`img`,`attachment`,`hidden`,`read`,`admin_id`,`create_time`,`update_time`) values (3,1,'Linux Kernel 权限提升漏洞预警','<!DOCTYPE html>\n<html>\n<head>\n</head>\n<body>\n<div data-version=\"3.0.0\" data-hash=\"c11d093dc7457991324a7190dffb08e4\">&nbsp;</div>\n<div>\n<div class=\"document\">\n<div class=\"section\">\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">尊敬的主题云用户：</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">您好！ 近日， Linux Kernel 被披露出存在本地提权漏洞，漏洞编号CVE-2022-0847。可导致linux本地提权等危害。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【漏洞评级】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">高风险</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【漏洞描述】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">CVE-2022-0847</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">攻击者通过利用此漏洞，可以覆盖任意可读文件中的数据，导致可将普通权限的用户提升至root权限。目前POC、 EXP已公开，风险较高。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【影响范围】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">主题云提供的云服务不受漏洞影响，请您及时安排自检内部自行搭建的环境并做好安全加固。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">影响版本：</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">5.8 &lt;= Linux kernel &lt; 5.16.11 / 5.15.25 / 5.10.102</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【修复方案】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">目前Kernel官方已提供安全版本修复了该漏洞，请受影响的用户及时升级至安全版本：https://www.kernel.org/</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【参考链接】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">https://access.redhat.com/security/cve/cve-2022-0847</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">https://dirtypipe.cm4all.com/</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/commit/?id=9d2231c5d74e13b2a0546fee6737ee4446017903</span></p>\n</div>\n</div>\n</div>\n</body>\n</html>','','','',0,0,1,1680240276,0);
insert  into `idcsmart_addon_idcsmart_announcement`(`id`,`addon_idcsmart_announcement_type_id`,`title`,`content`,`keywords`,`img`,`attachment`,`hidden`,`read`,`admin_id`,`create_time`,`update_time`) values (4,1,'Spring Framework 远程代码执行漏洞风险通告','<!DOCTYPE html>\n<html>\n<head>\n</head>\n<body>\n<div data-version=\"3.0.0\" data-hash=\"3ab54d8887ec458f6210a6b791a03809\">&nbsp;</div>\n<div>\n<div class=\"document\">\n<div class=\"section\">\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">尊敬的主题云用户：</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">您好！Spring官方发布安全公告，披露Spring Framework存在缺陷，导致运行在JDK 9及以上版本的环境上存在一处远程代码执行漏洞（CVE-2022-22965），该漏洞可导致远程写入、执行任意代码。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【漏洞评级】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">高风险</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【漏洞描述】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">CVE-2022-22965</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">据官方说明，目前已被泄漏的漏洞利用主要影响在 JDK 9+ 上运行的 Spring MVC 和 Spring WebFlux 应用程序。漏洞的成功利用需要应用程序作为 WAR 部署在 Tomcat 上运行。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【影响范围】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">影响版本：</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">Spring Framework 5.3.x &lt; 5.3.18</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">Spring Framework 5.2.x &lt; 5.2.20</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">并且使用了JDK版本 &gt;= 9</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">（其他Spring Framework低版本均有可能受影响）</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【修复方案】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">目前官方已发布安全版本，建议受影响的用户升级Spring Framework至安全版本：</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">https://github.com/spring-projects/spring-framework/tags</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【参考链接】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">https://spring.io/blog/2022/03/31/spring-framework-rce-early-announcement</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">https://tanzu.vmware.com/security/cve-2022-22965</span></p>\n</div>\n</div>\n</div>\n</body>\n</html>','','','',0,0,1,1680240299,0);
insert  into `idcsmart_addon_idcsmart_announcement`(`id`,`addon_idcsmart_announcement_type_id`,`title`,`content`,`keywords`,`img`,`attachment`,`hidden`,`read`,`admin_id`,`create_time`,`update_time`) values (5,1,'Jira 身份认证绕过漏洞','<!DOCTYPE html>\n<html>\n<head>\n</head>\n<body>\n<div data-version=\"3.0.0\" data-hash=\"0d6d6d6f3aa18054dfb5de9b5ab87a9e\">&nbsp;</div>\n<div>\n<div class=\"document\">\n<div class=\"section\">\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">尊敬的主题云用户：</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">您好！Atlassian官方发布安全公告，披露Atlassian Jira Seraph 存在身份验证绕过漏洞（CVE-2022-0540），为避免您的业务受影响建议您及时开展安全自查，如在受影响范围，请及时更新修复，避免被外部攻击者入侵。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【漏洞评级】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">高风险</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【漏洞描述】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">CVE-2022-0540</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">Jira是一个缺陷跟踪管理系统，为针对缺陷管理、任务追踪和项目管理的商业性应用软件。Jira Seraph是Jira 和 Jira Service Management 在 Web 身份验证的框架，未经身份验证的远程攻击者可利用Jira Seraph中的该漏洞，通过发送特制的 HTTP 请求绕过身份验证。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【影响范围】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">受影响的Jira版本：</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">Jira &lt; 8.13.18</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">Jira 8.14.x、8.15.x、8.16.x、8.17.x、8.18.x、8.19.x</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">Jira 8.20.x &lt; 8.20.6</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">Jira 8.21.x</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">受影响的Jira Service Management版本：</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">Jira Service Management &lt; 4.13.18</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">Jira Service Management 4.14.x、4.15.x、4.16.x、4.17.x、4.18.x、4.19.x</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">Jira Service Management 4.20.x &lt; 4.20.6</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">Jira Service Management 4.21.x</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【修复方案】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">目前官方已发布漏洞补丁及修复版本，请受影响的用户酌情升级至安全版本。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【参考链接】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">https://nvd.nist.gov/vuln/detail/CVE-2022-0540</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">https://jira.atlassian.com/browse/JSDSERVER-11224</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">https://confluence.atlassian.com/jira/jira-security-advisory-2022-04-20-1115127899.html</span></p>\n</div>\n</div>\n</div>\n</body>\n</html>','','','',0,0,1,1680240320,0);
insert  into `idcsmart_addon_idcsmart_announcement`(`id`,`addon_idcsmart_announcement_type_id`,`title`,`content`,`keywords`,`img`,`attachment`,`hidden`,`read`,`admin_id`,`create_time`,`update_time`) values (6,1,'Atlassian Confluence 远程代码执行漏洞预警','<!DOCTYPE html>\n<html>\n<head>\n</head>\n<body>\n<div data-version=\"3.0.0\" data-hash=\"e0be7f6ec1867ba30decd939907a6c66\">&nbsp;</div>\n<div>\n<div class=\"document\">\n<div class=\"section\">\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">尊敬的主题云用户：</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">您好！ Atlassian官方发布安全通告，披露了Confluence Server 和 Confluence Data Center中存在的一个远程代码执行漏洞，漏洞编号CVE-2022-26134。可导致攻击者无需身份验证远程执行任意代码等危害。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【漏洞评级】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">高风险</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【漏洞描述】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">CVE-2022-26134</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">JAtlassian Confluence是一个专业的企业知识管理与协同软件，可用于构建企业wiki，据官方描述，该漏洞由于Confluence Server 和 Data Center 版本中存在 OGNL表达式注入导致，可导致攻击者在未经身份验证的情况下，通过发送恶意请求，注入执行任意代码。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【影响范围】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">影响版本：</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">Atlassian Confluence Server and Data Center &gt;= 1.3.0</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">Atlassian Confluence Server and Data Center &lt; 7.4.17</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">Atlassian Confluence Server and Data Center &lt; 7.13.7</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">Atlassian Confluence Server and Data Center &lt; 7.14.3</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">Atlassian Confluence Server and Data Center &lt; 7.15.2</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">Atlassian Confluence Server and Data Center &lt; 7.16.4</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">Atlassian Confluence Server and Data Center &lt; 7.17.4</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">Atlassian Confluence Server and Data Center &lt; 7.18.1</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【修复方案】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">目前官方已发布漏洞补丁及修复版本，请受影响的用户酌情升级至安全版本：</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">https://www.atlassian.com/software/confluence/download-archives</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【参考链接】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">https://confluence.atlassian.com/doc/confluence-security-advisory-2022-06-02-1130377146.html</span></p>\n</div>\n</div>\n</div>\n</body>\n</html>','','','',0,0,1,1680240341,0);
insert  into `idcsmart_addon_idcsmart_announcement`(`id`,`addon_idcsmart_announcement_type_id`,`title`,`content`,`keywords`,`img`,`attachment`,`hidden`,`read`,`admin_id`,`create_time`,`update_time`) values (7,1,'Apache Spark 命令注入漏洞预警','<!DOCTYPE html>\n<html>\n<head>\n</head>\n<body>\n<div data-version=\"3.0.0\" data-hash=\"3844629fa9b908253e37222c7e195959\">&nbsp;</div>\n<div>\n<div class=\"document\">\n<div class=\"section\">\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">尊敬的主题云用户：</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">您好！ 近日，Apache Spark官方发布安全公告，披露在Apache Spark特定版本中存在一处命令注入漏洞（CVE-2022-33891）。Apache Spark UI具有ACL机制，当开启ACL后，攻击者可利用漏洞冒充任意用户进行任意命令注入并执行。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【漏洞评级】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">高风险</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【漏洞描述】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">CVE-2022-33891</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">Apache Spark 是专为大规模数据处理而设计的快速通用的计算引擎，是UC Berkeley AMP lab （加州大学伯克利分校的AMP实验室）所开源的类Hadoop MapReduce的通用并行框架。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">Apache Spark UI 中可通过配置选项 spark.acls.enable 启用 ACL 。这些身份验证过滤器会检查用户是否具有查看或修改应用程序的访问权限。如果启用ACL，则 HttpSecurityFilter 中的代码路径可允许攻击者冒充任意用户。该功能可根据他们的输入创建一个 Unix shell 命令并执行，最终导致执行任意命令。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【影响范围】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">Apache Spark =&lt; 3.0.3</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">Apache Spark 3.1.1 - 3.1.2</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">Apache Spark 3.2.0 - 3.2.1</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【修复方案】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">目前，官方已发布新版本修复了该漏洞，请受影响的用户升级到安全版本：</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">https://github.com/apache/spark/tags</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【参考链接】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">https://spark.apache.org/security.html</span></p>\n</div>\n</div>\n</div>\n</body>\n</html>','','','',0,0,1,1680240363,0);
insert  into `idcsmart_addon_idcsmart_announcement`(`id`,`addon_idcsmart_announcement_type_id`,`title`,`content`,`keywords`,`img`,`attachment`,`hidden`,`read`,`admin_id`,`create_time`,`update_time`) values (8,1,'Linux Kernel 权限提升漏洞预警','<!DOCTYPE html>\n<html>\n<head>\n</head>\n<body>\n<div data-version=\"3.0.0\" data-hash=\"8d79c66e2e82515c6921bbe8aae6c4a1\">&nbsp;</div>\n<div>\n<div class=\"document\">\n<div class=\"section\">\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">尊敬的主题云用户：</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">您好！ 近日， Linux kernel 被披露出存在本地提权漏洞，漏洞编号CVE-2022-2588，可导致攻击者权获得root权限等危害。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【漏洞评级】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">高风险</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【漏洞描述】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">CVE-2022-2588</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">漏洞由于在Linux kernel 的 net/sched/cls_route.c 过滤器实现的 route4_change 中存在 use-after-free 缺陷导致，若被本地经过身份认证的攻击者利用，可能会导致系统崩溃、权限提升等。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【影响范围】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">影响版本</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">Linux kernel &gt;= v2.6.12-rc2</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【修复方案】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">目前官方已在高版本中修复了该漏洞，请受影响的用户升级至安全版本：</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">https://www.kernel.org/</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【参考链接】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">https://github.com/Markakd/CVE-2022-2588</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\">&nbsp;</p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">https://access.redhat.com/security/cve/cve-2022-2588</span></p>\n</div>\n</div>\n</div>\n</body>\n</html>','','','',0,0,1,1680240382,0);
insert  into `idcsmart_addon_idcsmart_announcement`(`id`,`addon_idcsmart_announcement_type_id`,`title`,`content`,`keywords`,`img`,`attachment`,`hidden`,`read`,`admin_id`,`create_time`,`update_time`) values (9,1,'OpenSSL缓冲区溢出漏洞预警','<!DOCTYPE html>\n<html>\n<head>\n</head>\n<body>\n<div data-version=\"3.0.0\" data-hash=\"a4af6e4245e4b798c2ef471fbb0e7b3c\">&nbsp;</div>\n<div>\n<div class=\"document\">\n<div class=\"section\">\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">尊敬的主题云用户：</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">&nbsp; &nbsp;您好！ OpenSSL官方发布安全公告，披露在3.0.x版本中存在两处高危的缓冲区溢出漏洞（CVE-2022-3602、CVE-2022-3786），可导致拒绝服务等危害，在特定的情况下可能会导致远程代码执行。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【漏洞评级】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">高风险</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【漏洞描述】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">CVE-2022-3602、CVE-2022-3786</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">OpenSSL 是一个安全套接字层密码库，通常用于加密和安全通信。本次两处漏洞，都是由于OpenSSL 中X.509 证书验证时存在缺陷，攻击者可以通过制作恶意电子邮件地址触发缓冲区溢出，成功利用漏洞可导致拒绝服务或潜在的远程代码执行。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【影响范围】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">影响版本</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">3.0.0 &lt;= OpenSSL &lt; =3.0.6</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【修复方案】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">您可以使用 &ldquo;openssl version&rdquo; 或 &ldquo;openssl version -a&rdquo; 命令即可查看当前安装的openssl的版本。如使用版本受到漏洞潜在威胁，请尽快升级至安全版本：</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><a href=\"https://www.openssl.org/source/\"><span style=\"font-size: 10.5pt; font-family: 宋体; color: #0000ff; letter-spacing: 0pt; vertical-align: baseline; text-underline-position: under;\" data-font-family=\"宋体\">https://www.openssl.org/source/</span></a></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【参考链接】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">https://www.openssl.org/news/secadv/20221101.txt</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">https://www.openssl.org/blog/blog/2022/11/01/email-address-overflows/</span></p>\n</div>\n</div>\n</div>\n</body>\n</html>','','','',0,0,1,1680240429,0);
insert  into `idcsmart_addon_idcsmart_announcement`(`id`,`addon_idcsmart_announcement_type_id`,`title`,`content`,`keywords`,`img`,`attachment`,`hidden`,`read`,`admin_id`,`create_time`,`update_time`) values (10,1,'XStream 拒绝服务漏洞预警','<!DOCTYPE html>\n<html>\n<head>\n</head>\n<body>\n<div data-version=\"3.0.0\" data-hash=\"db760c5717f5a9e4922cd41389f615bd\">&nbsp;</div>\n<div>\n<div class=\"document\">\n<div class=\"section\">\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">尊敬的主题云用户：</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">&nbsp; &nbsp;您好！近日，Xstream官方发布安全公告，披露在1.4.20之前的版本中存在一处高风险级别的拒绝服务漏（CVE-2022-41966），目前漏洞细节已于POC公开，风险较高。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【漏洞评级】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">高风险</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【漏洞描述】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">CVE-2022-41966</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">本漏洞允许远程攻击者通过操纵已处理的输入流触发堆栈溢出，致使应用程序终止，从而导致拒绝服务。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【影响范围】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">影响版本</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">XStream &lt; 1.4.20</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【修复方案】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">目前官方已在高版本中修复了该漏洞，请受影响的用户升级至安全版本：</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">http://x-stream.github.io/download.html</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【参考链接】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">https://x-stream.github.io/CVE-2022-41966.html</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">https://github.com/x-stream/xstream/security/advisories/GHSA-j563-grx4-pjpv</span></p>\n</div>\n</div>\n</div>\n</body>\n</html>','','','',0,0,1,1680240450,0);
insert  into `idcsmart_addon_idcsmart_announcement`(`id`,`addon_idcsmart_announcement_type_id`,`title`,`content`,`keywords`,`img`,`attachment`,`hidden`,`read`,`admin_id`,`create_time`,`update_time`) values (11,1,'Apache Kafka Connect 远程代码执行漏洞预警','<!DOCTYPE html>\n<html>\n<head>\n</head>\n<body>\n<div data-version=\"3.0.0\" data-hash=\"6be7545a0e09c4b96c45e095bcd4418f\">&nbsp;</div>\n<div>\n<div class=\"document\">\n<div class=\"section\">\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">尊敬的主题云用户：</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">&nbsp; &nbsp;您好！近日，Apache Kafka官方发布安全公告，披露在Apache Kafka特定版本中存在一处远程代码执行漏洞（CVE-2023-25194），目前POC已公开，风险较高。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【漏洞评级】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">高风险</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【漏洞描述】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">CVE-2023-25194</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">Apache Kafka 是一个分布式数据流处理平台，Kafka Connect 是一种工具，用于在 Apache Kafka 和其他数据系统之间以可扩展且可靠的方式传输数据。当通过 Kafka Connect REST API 配置连接器时，经过身份验证的攻击者可以通过修改连接器的Kafka 客户端属性配置进行JNDI注入攻击，最终可导致在目标服务器上执行任意代码。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【影响范围】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">影响版本</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">Apache Kafka 2.3.0 - 3.3.2</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【修复方案】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">目前，官方已发布新版本修复了该漏洞，请受影响的用户升级到安全版本：</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">https://github.com/apache/Kafka/tags</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">【参考链接】</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">https://kafka.apache.org/cve-list</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">https://lists.apache.org/thread/rn8vn4d9dbxc6817c5wz1dhhoshp1s25</span></p>\n</div>\n</div>\n</div>\n</body>\n</html>','','','',0,0,1,1680240477,0);
insert  into `idcsmart_addon_idcsmart_announcement`(`id`,`addon_idcsmart_announcement_type_id`,`title`,`content`,`keywords`,`img`,`attachment`,`hidden`,`read`,`admin_id`,`create_time`,`update_time`) values (12,2,'主题云2022年春节放假公告','<!DOCTYPE html>\n<html>\n<head>\n</head>\n<body>\n<div data-version=\"3.0.0\" data-hash=\"a43c4ff2d85cb9cd26ea7a045161efcc\">&nbsp;</div>\n<div>\n<div class=\"document\">\n<div class=\"section\">\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">尊敬的主题云用户</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">您好！</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">2022虎年将至，值此新春佳节来临之际，主题云全体员工祝您虎年大吉！</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">根据国家春节放假规定并结合我司实际经营情况，主题云春节放假时间为：2022年1月31日至2月6日。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">放假期间，我们将继续为您提供7*24不间断工单以及全国客服热线电话支持，持续为您的云端业务保驾护航，同时也请您关注一下业务：</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">1.账号、计费注意事项</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">（1）按量计费（后付费）资源：请您务必关注主题云账户余额，提前充值，防止长假期间发生欠费停服。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">（2）包年包月（预付费）资源：请您务必关注包年包月资源的到期时间，提前进行续费，避免到期停服。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">2.发票审核及邮寄：</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">为降低春节期间发票邮寄后丢失的风险，我们将在1月27日17：00进行放假前最后一次邮寄，此后申请的发票将于2月7日正式上班后尽快发出。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">感谢您的信任与支持，祝您新春快乐、事业顺心、身体健康、万事如意！</span></p>\n<p class=\"paragraph text-align-type-right\" style=\"margin: 0pt 0pt 7.8pt; text-align: right; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">主题云</span></p>\n<p class=\"paragraph text-align-type-right\" style=\"margin: 0pt 0pt 7.8pt; text-align: right; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">2022年1月25日</span></p>\n</div>\n</div>\n</div>\n</body>\n</html>','','','',0,0,1,1680240599,0);
insert  into `idcsmart_addon_idcsmart_announcement`(`id`,`addon_idcsmart_announcement_type_id`,`title`,`content`,`keywords`,`img`,`attachment`,`hidden`,`read`,`admin_id`,`create_time`,`update_time`) values (13,2,'主题云会员中心服务升级通知','<!DOCTYPE html>\n<html>\n<head>\n</head>\n<body>\n<div data-version=\"3.0.0\" data-hash=\"e5d13b8c655d740459f4394bdafa9ed3\">&nbsp;</div>\n<div>\n<div class=\"document\">\n<div class=\"section\">\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">尊敬的主题云用户：</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">您好！</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">为给您提供更好的服务体验，主题云计划将在2022年2月19日晚22:00-23:00对会员中心系统进行服务升级，升级期间不影响您的业务正常运行，但该时间段可能无法进行充值、续费等操作，请您关注账户余额以及各项服务到期时间，如有需要请提前做好准备。如在升级期间遇到问题，可提交工单或拨打主题云24小时客服热线，感谢您的理解与支持。</span></p>\n<p class=\"paragraph text-align-type-right\" style=\"margin: 0pt 0pt 7.8pt; text-align: right; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">主题云</span></p>\n<p class=\"paragraph text-align-type-right\" style=\"margin: 0pt 0pt 7.8pt; text-align: right; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">2022年2月17 日</span></p>\n</div>\n</div>\n</div>\n</body>\n</html>','','','',0,0,1,1680240619,0);
insert  into `idcsmart_addon_idcsmart_announcement`(`id`,`addon_idcsmart_announcement_type_id`,`title`,`content`,`keywords`,`img`,`attachment`,`hidden`,`read`,`admin_id`,`create_time`,`update_time`) values (14,2,'主题云2022年五一放假公告','<!DOCTYPE html>\n<html>\n<head>\n</head>\n<body>\n<div data-version=\"3.0.0\" data-hash=\"5e7f8d4c219c65bc54a7854e0ded425a\">&nbsp;</div>\n<div>\n<div class=\"document\">\n<div class=\"section\">\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">尊敬的主题云用户：</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">您好！2022年五一假期将近，主题云祝您五一快乐！根据国家相关规定并结合我司实际经营情况，现将主题云五一放假安排公布如下：</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">&middot;放假时间</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">2022年4月30日至5月4日</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">&middot;假期服务通道</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">自助服务：您可以在主题云的帮助文档中快速找到大部分问题的解决方案。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">提交工单：专业工程师将根据您的诉求尽快排查并予以解决。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">客服热线：如果事出紧急，您可以直接拨打主题云官方客服热线，售后工程师24小时在线。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">&middot;充值与续费</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">所有线上服务正常运行不受影响，放假期间仍然可以正常充值与续费。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">&middot;发票与合同</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">为降低五一期间寄送丢失等风险，我们将在4月29日17:00暂停邮寄纸质发票与纸质合同，5月5日09:00恢复。五一放假期间，您可以正常申请并获得电子发票与电子合同。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">感谢您对主题云的信赖与支持，祝您节日愉快！</span></p>\n<p class=\"paragraph text-align-type-right\" style=\"margin: 0pt 0pt 7.8pt; text-align: right; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">主题云</span></p>\n<p class=\"paragraph text-align-type-right\" style=\"margin: 0pt 0pt 7.8pt; text-align: right; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">2022年4月25日</span></p>\n</div>\n</div>\n</div>\n</body>\n</html>','','','',0,0,1,1680240635,0);
insert  into `idcsmart_addon_idcsmart_announcement`(`id`,`addon_idcsmart_announcement_type_id`,`title`,`content`,`keywords`,`img`,`attachment`,`hidden`,`read`,`admin_id`,`create_time`,`update_time`) values (15,2,'服务等级协议更新公告','<!DOCTYPE html>\n<html>\n<head>\n</head>\n<body>\n<div data-version=\"3.0.0\" data-hash=\"c4e56ebf8f588af1b47f2750f9aac068\">&nbsp;</div>\n<div>\n<div class=\"document\">\n<div class=\"section\">\n<p class=\"paragraph text-align-type-left\" style=\"margin: 0pt 0pt 7.8pt; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">尊敬的主题云用户：</span></p>\n<p class=\"paragraph text-align-type-left\" style=\"margin: 0pt 0pt 7.8pt; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">我们于2022年6月8日更新了服务等级协议，更新后的服务等级协议将于2022年7月1日生效。</span></p>\n<p class=\"paragraph text-align-type-left\" style=\"margin: 0pt 0pt 7.8pt; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">请您在使用或继续使用我们的产品与服务前仔细阅读和充分理解协议内容，并在同意全部内容后使用或继续使用本公司产品与服务。</span></p>\n<p class=\"paragraph text-align-type-left\" style=\"margin: 0pt 0pt 7.8pt; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">感谢您的支持与信赖。</span></p>\n<p class=\"paragraph text-align-type-right\" style=\"margin: 0pt 0pt 7.8pt; text-align: right; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">主题云</span></p>\n<p class=\"paragraph text-align-type-right\" style=\"margin: 0pt 0pt 7.8pt; text-align: right; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">2022年6月8日</span></p>\n</div>\n</div>\n</div>\n</body>\n</html>','','','',0,0,1,1680240653,0);
insert  into `idcsmart_addon_idcsmart_announcement`(`id`,`addon_idcsmart_announcement_type_id`,`title`,`content`,`keywords`,`img`,`attachment`,`hidden`,`read`,`admin_id`,`create_time`,`update_time`) values (16,2,'主题云2022年国庆放假公告','<!DOCTYPE html>\n<html>\n<head>\n</head>\n<body>\n<div data-version=\"3.0.0\" data-hash=\"85c6e955e84b8f5ef18f3d6c4c608961\">&nbsp;</div>\n<div>\n<div class=\"document\">\n<div class=\"section\">\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">尊敬的主题云用户：</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">盛世华诞，举国同庆！主题云热烈庆祝中华人民共和国成立73周年，祝您国庆快乐！根据国家相关规定并结合我司实际经营情况，现将主题云国庆放假安排公布如下：</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">&middot;放假时间</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">2022年10月1日至10月7日</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">&middot;假期服务通道</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">自助服务：您可以在主题云的帮助文档中快速找到大部分问题的解决方案。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">提交工单：专业工程师将根据您的诉求尽快排查并予以解决。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">客服热线：如果事出紧急，您可以直接拨打主题云官方客服热线，售后工程师24小时在线。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">&middot;充值与续费</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">所有线上服务正常运行不受影响，放假期间仍然可以正常充值与续费。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">&middot;发票与合同</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">为降低国庆期间寄送丢失等风险，我们将在9月30日17:00暂停邮寄纸质发票与纸质合同，10月8日09:00恢复。国庆放假期间，您可以正常申请并获得电子发票与电子合同。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">感谢您对主题云的信赖与支持，祝您节日愉快！</span></p>\n<p class=\"paragraph text-align-type-right\" style=\"margin: 0pt 0pt 7.8pt; text-align: right; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">主题云</span></p>\n<p class=\"paragraph text-align-type-right\" style=\"margin: 0pt 0pt 7.8pt; text-align: right; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">2022年9月27日</span></p>\n</div>\n</div>\n</div>\n</body>\n</html>','','','',0,0,1,1680240679,0);
insert  into `idcsmart_addon_idcsmart_announcement`(`id`,`addon_idcsmart_announcement_type_id`,`title`,`content`,`keywords`,`img`,`attachment`,`hidden`,`read`,`admin_id`,`create_time`,`update_time`) values (17,2,'主题云元旦大促，云服务器低至2.5折！','<!DOCTYPE html>\n<html>\n<head>\n</head>\n<body>\n<div data-version=\"3.0.0\" data-hash=\"c866bb7d9e0db3a87e0b4604d34fe9ea\">&nbsp;</div>\n<div>\n<div class=\"document\">\n<div class=\"section\">\n<p class=\"paragraph text-align-type-left\" style=\"margin: 0pt 0pt 7.8pt; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">尊敬的主题云用户：</span></p>\n<p class=\"paragraph text-align-type-left\" style=\"margin: 0pt 0pt 7.8pt; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">主题云的&ldquo;元旦大促&rdquo;促销将于2023年1月1日零点正式开始，并于当天晚间23:59:59结束。</span></p>\n<p class=\"paragraph text-align-type-left\" style=\"margin: 0pt 0pt 7.8pt; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">无论您是购新还是续费，凡在此时间段购买云服务器的顾客都将享受以下优惠：</span></p>\n<p class=\"paragraph text-align-type-left\" style=\"margin: 0pt 0pt 7.8pt; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">1.当您选择5年时长，您将享受2.5折优惠；</span></p>\n<p class=\"paragraph text-align-type-left\" style=\"margin: 0pt 0pt 7.8pt; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">2.当您选择3年时长，您将享受5折优惠；</span></p>\n<p class=\"paragraph text-align-type-left\" style=\"margin: 0pt 0pt 7.8pt; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">3.当您选择2年时长，您将享受6折优惠；</span></p>\n<p class=\"paragraph text-align-type-left\" style=\"margin: 0pt 0pt 7.8pt; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">4.当您选择的时长在1年以内，您将享受8折优惠；</span></p>\n<p class=\"paragraph text-align-type-left\" style=\"margin: 0pt 0pt 7.8pt; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">我们真诚地希望每位客户都能得到最实惠的价格，但因各地区的云服务器实例有限，希望有需求的客户提前下单，避免资源不足。</span></p>\n<p class=\"paragraph text-align-type-right\" style=\"margin: 0pt 0pt 7.8pt; text-align: right; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">主题云</span></p>\n<p class=\"paragraph text-align-type-right\" style=\"margin: 0pt 0pt 7.8pt; text-align: right; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">2022年12月30日</span></p>\n</div>\n</div>\n</div>\n</body>\n</html>','','','',0,0,1,1680240695,0);
insert  into `idcsmart_addon_idcsmart_announcement`(`id`,`addon_idcsmart_announcement_type_id`,`title`,`content`,`keywords`,`img`,`attachment`,`hidden`,`read`,`admin_id`,`create_time`,`update_time`) values (18,2,'主题云2023年春节放假公告','<!DOCTYPE html>\n<html>\n<head>\n</head>\n<body>\n<div data-version=\"3.0.0\" data-hash=\"70ea9d9db27f9ac91b6b9a76bcd5f2ba\">&nbsp;</div>\n<div>\n<div class=\"document\">\n<div class=\"section\">\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">尊敬的主题云用户：</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">虎年辞旧岁，兔年迎新春！2023年新春佳节将至，主题云全体员工恭祝您新春快乐、兔年大吉！同时附上主题云春节期间（2023年1月21日至1月27日）的服务安排，请您了解并提前做好相关安排。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">&middot;服务通道</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">自助服务：您可以在主题云的帮助文档中快速找到大部分问题的解决方案。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">提交工单：专业工程师将根据您的诉求尽快排查并予以解决。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">客服热线：如果事出紧急，您可以直接拨打主题云官方客服热线，售后工程师24小时在线为您服务。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">&middot;充值与续费</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">所有线上服务正常运行不受影响，放假期间仍然可以正常充值与续费。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">&middot;发票与合同</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">为降低春节期间邮件丢失风险，我们将在1月15日17:00暂停邮寄纸质发票与纸质合同，1月28日09:00恢复。春节放假期间，您可以正常申请并获得电子发票与电子合同。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">感谢您对主题云的信赖与支持，祝您节日愉快！</span></p>\n<p class=\"paragraph text-align-type-right\" style=\"margin: 0pt 0pt 7.8pt; text-align: right; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">主题云</span></p>\n<p class=\"paragraph text-align-type-right\" style=\"margin: 0pt 0pt 7.8pt; text-align: right; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">2023年1月23日</span></p>\n</div>\n</div>\n</div>\n</body>\n</html>','','','',0,0,1,1680240713,1680240751);
insert  into `idcsmart_addon_idcsmart_announcement`(`id`,`addon_idcsmart_announcement_type_id`,`title`,`content`,`keywords`,`img`,`attachment`,`hidden`,`read`,`admin_id`,`create_time`,`update_time`) values (19,2,'主题云2023年五一放假公告','<!DOCTYPE html>\n<html>\n<head>\n</head>\n<body>\n<div data-version=\"3.0.0\" data-hash=\"cba4d12215fc88ef8ac7a7d45dbb8a96\">&nbsp;</div>\n<div>\n<div class=\"document\">\n<div class=\"section\">\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">尊敬的主题云用户：</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">您好！五一假期将近，主题云提前祝您五一快乐！根据国家相关规定并结合我司实际经营情况，现将主题云五一放假安排公布如下：</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">&middot;放假时间</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">2022年4月29日至5月3日</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">&middot;假期服务通道</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">自助服务：您可以在主题云的帮助文档中快速找到大部分问题的解决方案。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">提交工单：专业工程师将根据您的诉求尽快排查并予以解决。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">客服热线：如果事出紧急，您可以直接拨打主题云官方客服热线，售后工程师24小时在线。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">&middot;充值与续费</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">所有线上服务正常运行不受影响，放假期间仍然可以正常充值与续费。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">&middot;发票与合同</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">为降低五一期间寄送丢失等风险，我们将在4月28日17:00暂停邮寄纸质发票与纸质合同，5月4日09:00恢复。五一放假期间，您可以正常申请并获得电子发票与电子合同。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">感谢您对主题云的信赖与支持，祝您节日愉快！</span></p>\n<p class=\"paragraph text-align-type-right\" style=\"margin: 0pt 0pt 7.8pt; text-align: right; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">主题云</span></p>\n<p class=\"paragraph text-align-type-right\" style=\"margin: 0pt 0pt 7.8pt; text-align: right; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">2023年4月24日</span></p>\n</div>\n</div>\n</div>\n</body>\n</html>','','','',0,0,1,1680240728,0);
insert  into `idcsmart_addon_idcsmart_announcement`(`id`,`addon_idcsmart_announcement_type_id`,`title`,`content`,`keywords`,`img`,`attachment`,`hidden`,`read`,`admin_id`,`create_time`,`update_time`) values (20,2,'主题云交易支付系统升级公告','<!DOCTYPE html>\n<html>\n<head>\n</head>\n<body>\n<div data-version=\"3.0.0\" data-hash=\"4e8083ff8ef23351458fce5fb2171c14\">&nbsp;</div>\n<div>\n<div class=\"document\">\n<div class=\"section\">\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">尊敬的主题云用户：</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">为优化交易支付系统，我团队计划于2023年7月10日凌晨01:00-02:00对交易支付系统进行升级。升级期间订单交易系统对外停服，涉及订单的操作将无法进行，请您尽量避开此时间段进行资源创建、下单、续费、充值、提现、开票、申请合同等操作，请广大新老客户提前做好相关准备工作。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">由此给您带来的不便我们深表歉意，感谢您的信赖与支持！</span></p>\n<p class=\"paragraph text-align-type-right\" style=\"margin: 0pt 0pt 7.8pt; text-align: right; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">主题云</span></p>\n<p class=\"paragraph text-align-type-right\" style=\"margin: 0pt 0pt 7.8pt; text-align: right; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">2023年7月8日</span></p>\n</div>\n</div>\n</div>\n</body>\n</html>','','','',0,0,1,1680240744,0);
insert  into `idcsmart_addon_idcsmart_announcement`(`id`,`addon_idcsmart_announcement_type_id`,`title`,`content`,`keywords`,`img`,`attachment`,`hidden`,`read`,`admin_id`,`create_time`,`update_time`) values (21,2,'主题云2023年中秋国庆放假公告','<!DOCTYPE html>\n<html>\n<head>\n</head>\n<body>\n<div data-version=\"3.0.0\" data-hash=\"89d51557eb87f5ab0d29e78cc0ab9fea\">&nbsp;</div>\n<div>\n<div class=\"document\">\n<div class=\"section\">\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">尊敬的主题云用户：</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">您好！中秋国庆双节将至，主题云提前祝您中秋安康、国庆快乐！根据国家相关规定并结合我司实际经营情况，现将主题云中秋国庆放假安排公布如下：</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">&middot;放假时间</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">2023年9月29日至10月6日</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">&middot;假期服务通道</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">自助服务：您可以在主题云的帮助文档中快速找到大部分问题的解决方案。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">提交工单：专业工程师将根据您的诉求尽快排查并予以解决。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">客服热线：如果事出紧急，您可以直接拨打主题云官方客服热线，售后工程师24小时在线。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">&middot;充值与续费</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">所有线上服务正常运行不受影响，放假期间仍然可以正常充值与续费。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">&middot;发票与合同</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">为降低国庆期间寄送丢失等风险，我们将在9月28日17:00暂停邮寄纸质发票与纸质合同，10月7日09:00恢复。国庆放假期间，您可以正常申请并获得电子发票与电子合同。</span></p>\n<p class=\"paragraph text-align-type-justify\" style=\"margin: 0pt 0pt 7.8pt; text-align: justify; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">感谢您对主题云的信赖与支持，祝您节日愉快！</span></p>\n<p class=\"paragraph text-align-type-right\" style=\"margin: 0pt 0pt 7.8pt; text-align: right; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">主题云</span></p>\n<p class=\"paragraph text-align-type-right\" style=\"margin: 0pt 0pt 7.8pt; text-align: right; font-family: 等线; font-size: 12pt; line-height: 24px; text-indent: 21pt;\"><span style=\"font-size: 10.5pt; font-family: 宋体; letter-spacing: 0pt; vertical-align: baseline;\" data-font-family=\"宋体\">2023年9月22日</span></p>\n</div>\n</div>\n</div>\n</body>\n</html>','','','',0,0,1,1680240772,0);
