insert  into `idcsmart_addon_idcsmart_help`(`id`,`addon_idcsmart_help_type_id`,`title`,`content`,`keywords`,`attachment`,`hidden`,`index_hidden`,`read`,`admin_id`,`create_time`,`update_time`,`cron_release`,`cron_release_time`) values (8,3,'如何修改账号','<!DOCTYPE html>\n<html>\n<head>\n</head>\n<body>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">当您完成注册后，如果手机号码或邮箱等注册信息发生变更，可以在</span> </span><strong><span style=\"font-family: 宋体; color: #0000ff; font-size: 10.5pt;\">账户信息</span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;<span style=\"font-family: 宋体;\">页面修改账号。如原账号（手机号码</span><span style=\"font-family: Calibri;\">/</span><span style=\"font-family: 宋体;\">邮箱）已不能使用，请联系商务或提交工单，具体操作请参见 </span></span><strong><span style=\"font-family: 宋体; color: #0000ff; font-size: 10.5pt;\">如何提交工单</span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;<span style=\"font-family: 宋体;\">。</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><strong><span style=\"font-family: 宋体; color: #0000ff; font-size: 10.5pt;\">&middot;修改手机号码</span></strong></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><strong><span style=\"font-family: 宋体; color: #0000ff; font-size: 10.5pt;\">&middot;修改邮箱</span></strong></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">修改账号</span></strong></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\"><span style=\"font-family: Calibri;\">1.</span><span style=\"font-family: 宋体;\">修改手机号码</span></span></strong></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">①在会员中心点击 </span><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">&ldquo;</span></strong><strong><span style=\"font-family: 宋体; color: #0000ff; font-size: 10.5pt;\">账户信息</span></strong><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">&rdquo;</span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;<span style=\"font-family: 宋体;\">，在</span> </span><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">&ldquo;手机&rdquo;</span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;<span style=\"font-family: 宋体;\">栏点击</span><span style=\"font-family: 宋体;\">&ldquo;</span></span><img src=\"data:image/png;base64,\" alt=\"\" /><span style=\"font-family: 宋体; font-size: 10.5pt;\">&rdquo; 。</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">图</span><span style=\"font-family: Calibri;\">1</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><img src=\"data:image/png;base64,\" alt=\"\" /><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-fareast-font-family: 宋体; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"font-family: 宋体; font-size: 10.5pt;\">②如下图所示，在弹窗中</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">点击</span><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">&nbsp;<span style=\"font-family: 宋体;\">&ldquo;获取验证码&rdquo;</span></span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;<span style=\"font-family: 宋体;\">后输入正确的验证码，点击</span> </span><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">&ldquo;验证&rdquo;</span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;<span style=\"font-family: 宋体;\">完成身份验证，以确保您的账户安全。</span></span></p>\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">图</span><span style=\"font-family: Calibri;\">2</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><img src=\"data:image/png;base64,\" alt=\"\" /><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-fareast-font-family: 宋体; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"font-family: 宋体; font-size: 10.5pt;\">③完成验证后，在接下来的弹窗中输入新的手机号码，点击</span><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">&nbsp;<span style=\"font-family: 宋体;\">&ldquo;获取验证码&rdquo;</span></span></strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">&nbsp;<span style=\"font-family: 宋体;\">后输入验证码点击</span> </span><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">&ldquo;验证&rdquo; </span></strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">即可完成修改。</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><span style=\"font-family: 宋体; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">图</span><span style=\"font-family: Calibri;\">3</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><img src=\"data:image/png;base64,\" alt=\"\" /><span style=\"font-family: Calibri; font-size: 10.5pt;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\"><span style=\"font-family: Calibri;\">2.</span><span style=\"font-family: 宋体;\">修改邮箱</span></span></strong></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"mso-spacerun: \'yes\'; fon