insert  into `idcsmart_addon_idcsmart_help`(`id`,`addon_idcsmart_help_type_id`,`title`,`content`,`keywords`,`attachment`,`hidden`,`index_hidden`,`read`,`admin_id`,`create_time`,`update_time`,`cron_release`,`cron_release_time`) values (12,3,'如何设置IP白名单','<!DOCTYPE html>\n<html>\n<head>\n</head>\n<body>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">如果您希望只允许指定</span><span style=\"font-family: Calibri;\">IP</span><span style=\"font-family: 宋体;\">地址可以进行</span><span style=\"font-family: Calibri;\">API</span><span style=\"font-family: 宋体;\">调用，可开启 </span></span><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\"><span style=\"font-family: Calibri;\">IP</span><span style=\"font-family: 宋体;\">白名单</span></span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;<span style=\"font-family: 宋体;\">功能。</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">注意