insert  into `idcsmart_addon_idcsmart_help`(`id`,`addon_idcsmart_help_type_id`,`title`,`content`,`keywords`,`attachment`,`hidden`,`index_hidden`,`read`,`admin_id`,`create_time`,`update_time`,`cron_release`,`cron_release_time`) values (17,4,'如何续费','<!DOCTYPE html>\n<html>\n<head>\n</head>\n<body>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">如果您购买的产品即将到期，我们会提前向您发送到期提醒与续费通知，如果您希望继续使用我们的产品与服务，可在产品详情页进行产品续费，或开通</span><span style=\"font-family: 宋体;\">&ldquo;自动续费&rdquo;功能，系统将自动扣款续期。</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><strong><span style=\"font-family: 宋体; color: #0000ff; font-size: 10.5pt;\">&middot;手动续费</span></strong></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><strong><span style=\"font-family: 宋体; color: #0000ff; font-size: 10.5pt;\">&middot;自动续费</span></strong></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-fareast-font-family: 宋体; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">操作步骤</span></strong></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\"><span style=\"font-family: Calibri;\">1.</span><span style=\"font-family: 宋体;\">手动续费</span></span></strong></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"font-family: 宋体; font-size: 10.5pt;\">①在</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">会员中心，点击进入已购产品列表。如下图（图</span><span style=\"font-family: Calibri;\">1</span><span style=\"font-family: 宋体;\">），点击 </span></span><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">&ldquo;云服务器&rdquo; </span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">进入已购云服务器列表。</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">图</span><span style=\"font-family: Calibri;\">1</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><img src=\"data:image/png;base64,\" alt=\"\" /><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-fareast-font-family: 宋体; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">②选择需要续费的产品，点击进入产品详情页。</span></p>\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">图</span><span style=\"font-family: Calibri;\">2</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><img src=\"data:image/png;base64,\" alt=\"\" /><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">③在产品详情页的 &ldquo;支付信息&rdquo; 栏中，可查看 &ldquo;下次续费金额&rdquo; ，点击 </span><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">&ldquo;续费&rdquo;</span></strong></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">图</span><span style=\"font-family: Calibri;\">3</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><img src=\"data:image/png;base64,\" alt=\"\" /><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">④在弹窗页面完成续费。您还可以选择&ldquo;使用代金券&rdquo;或&ldquo;使用优惠码&rdquo;完成支付。</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">图</span><span style=\"font-family: Calibri;\">4</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><img src=\"data:image/png;base64,\" alt=\"\" /><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-fareast-font-family: 宋体; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\"><span style=\"font-family: Calibri;\">2.</span><span style=\"font-family: 宋体;\">自动续费</span></span></strong></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">①您也可以在产品详情页&ldquo;支付信息栏&rdquo;中，一键开通 </span><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">&ldquo;自动续费&rdquo;</span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;<span style=\"font-family: 宋体;\">功能。</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">图</span><span style=\"font-family: Calibri;\">5</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><img src=\"data:image/png;base64,\" alt=\"\" /><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-fareast-font-family: 宋体; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.85pt; line-height: 130%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">②在弹窗页面确认产品信息，点击&ldquo;提交&rdquo;即可开通自动续费功能。</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">图</span><span style=\"font-family: Calibri;\">6</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><img src=\"data:image/png;base64,\" alt=\"\" /><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">③开通自动续费功能后，我们将在您账户余额充足的情况下自动扣费，不再为您发送续费通知。</span></p>\n</body>\n</html>','','',0,0,2,1,1673342443,0,0,0);
insert  into `idcsmart_addon_idcsmart_help`(`id`,`addon_idcsmart_help_type_id`,`title`,`content`,`keywords`,`attachment`,`hidden`,`index_hidden`,`read`,`admin_id`,`create_time`,`update_time`,`cron_release`,`cron_release_time`) values (18,4,'如何申请产品停用','<!DOCTYPE html>\n<html>\n<head>\n</head>\n<body>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">如果您不希望继续使用已购买的产品，可申请停用，我们支持您选择</span><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">&nbsp;<span style=\"font-family: 宋体;\">&ldquo;立即停用&rdquo; </span></span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">或</span><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">&nbsp;<span style=\"font-family: 宋体;\">&ldquo;到期停用&rdquo;</span></span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;<span style=\"font-family: 宋体;\">。</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">操作步骤</span></strong></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">①登录会员中心，进入对应产品详情页，点击右上角 </span><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">&ldquo;申请停用&rdquo; </span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">。</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">图</span><span style=\"font-family: Calibri;\">1</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><img src=\"data:image/png;base64,\" alt=\"\" /><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-fareast-font-family: 宋体; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">②在弹窗中确认产品信息，填写 </span><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">&ldquo;停用原因&rdquo;</span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;<span style=\"font-family: 宋体;\">，停用时间选择</span></span><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">&nbsp;<span style=\"font-family: 宋体;\">&ldquo;立即&rdquo;</span></span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;<span style=\"font-family: 宋体;\">或</span> </span><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">&ldquo;到期&rdquo;</span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;<span style=\"font-family: 宋体;\">，点击</span></span><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">&nbsp;<span style=\"font-family: 宋体;\">&ldquo;确认停用&rdquo;</span></span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;<span style=\"font-family: 宋体;\">即可。</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">图</span><span style=\"font-family: Calibri;\">2</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><img src=\"data:image/png;base64,\" alt=\"\" /><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-fareast-font-family: 宋体; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">③如果您选择</span><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">&nbsp;<span style=\"font-family: 宋体;\">&ldquo;立即停用&rdquo; </span></span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，我们将在申请当天</span><span style=\"font-family: Calibri;\">24</span><span style=\"font-family: 宋体;\">点后自动为您停用对应产品及服务。如果您希望继续使用该产品，可在当天</span><span style=\"font-family: Calibri;\">24</span><span style=\"font-family: 宋体;\">点之前 </span></span><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">&ldquo;取消停用&rdquo;</span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">。</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">图</span><span style=\"font-family: Calibri;\">3</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><img src=\"data:image/png;base64,\" alt=\"\" /><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-fareast-font-family: 宋体; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">④如果您选择 </span><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">&ldquo;到期停用&rdquo;</span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;<span style=\"font-family: 宋体;\">，产品状态将变更为</span></span><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">&nbsp;<span style=\"font-family: 宋体;\">&ldquo;待停用&rdquo;</span></span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;<span style=\"font-family: 宋体;\">，我们将在到期时间后自动停用并删除该产品信息。如果您之后希望继续使用该产品，可在到期停用前点击</span> </span><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">&ldquo;取消停用&rdquo;</span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;<span style=\"font-family: 宋体;\">。</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">图</span><span style=\"font-family: Calibri;\">4</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><img src=\"data:image/png;base64,\" alt=\"\" /><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-fareast-font-family: 宋体; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\n</body>\n</html>','','',0,0,2,1,1673342523,0,0,0);
insert  into `idcsmart_addon_idcsmart_help`(`id`,`addon_idcsmart_help_type_id`,`title`,`content`,`keywords`,`attachment`,`hidden`,`index_hidden`,`read`,`admin_id`,`create_time`,`update_time`,`cron_release`,`cron_release_time`) values (19,5,'如何领取或查看的代金券','<!DOCTYPE html>\n<html>\n<head>\n</head>\n<body>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">我们会不定期在网站发布优惠活动信息，您可以直接在活动页面领取代金券，也可以在</span><span style=\"font-family: 宋体;\">&ldquo;财务信息&rdquo;模块查看并领取代金券。</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><strong><span style=\"font-family: 宋体; color: #0000ff; font-size: 10.5pt;\">&middot;领取代金券</span></strong></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><strong><span style=\"font-family: 宋体; color: #0000ff; font-size: 10.5pt;\">&middot;查看已领取的代金券</span></strong></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">操作步骤</span></strong></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\"><span style=\"font-family: Calibri;\">1.</span><span style=\"font-family: 宋体;\">领取代金券</span></span></strong></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">①通过官网活动页面领取代金券。</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">②登录会员中心，点击 </span><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">&ldquo;财务信息&rdquo;</span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;<span style=\"font-family: 宋体;\">，选择</span> </span><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">&ldquo;我的代金券&rdquo;</span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;<span style=\"font-family: 宋体;\">。</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">图</span><span style=\"font-family: Calibri;\">1</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><img src=\"data:image/png;base64,\" alt=\"\" /><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">③点击左上角 </span><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">&ldquo;我要领券&rdquo;</span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;<span style=\"font-family: 宋体;\">，可查看当前可领取的代金券。</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">图</span><span style=\"font-family: Calibri;\">2</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.85pt; line-height: 130%; text-align: center;\"><img src=\"data:image/png;base64,\" alt=\"\" /><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-fareast-font-family: 宋体; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">⑤在领券页面点击 </span><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">&ldquo;立即领取&rdquo;</span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;<span style=\"font-family: 宋体;\">，即可领取对应的代金券。</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">图</span><span style=\"font-family: Calibri;\">3</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><img src=\"data:image/png;base64,\" alt=\"\" /><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-fareast-font-family: 宋体; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\"><span style=\"font-family: Calibri;\">2.</span><span style=\"font-family: 宋体;\">查看代金券</span></span></strong></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">③领取代金券后，</span><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">&ldquo;我的代金券&rdquo; </span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">页面将展示您已领取的代金券信息。</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">图</span><span style=\"font-family: Calibri;\">4</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><img src=\"data:image/png;base64,\" alt=\"\" /><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\n</body>\n</html>','','',0,0,2,1,1673342631,0,0,0);
insert  into `idcsmart_addon_idcsmart_help`(`id`,`addon_idcsmart_help_type_id`,`title`,`content`,`keywords`,`attachment`,`hidden`,`index_hidden`,`read`,`admin_id`,`create_time`,`update_time`,`cron_release`,`cron_release_time`) values (20,5,'如何申请开具发票','<!DOCTYPE html>\n<html>\n<head>\n</head>\n<body>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">您在我们官网上购买任何商品或服务，都可以申请开具发票。您可以在付款后申请开具发票，也可以在与我们达成合作意向后申请预开发票。</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">注意事项</span></strong></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"font-family: 宋体; font-size: 10.5pt;\">在申请开具发票之前，请先设置发票抬头与收件地址。具体操作请参见</span><strong><span style=\"font-family: 宋体; color: #0000ff; font-size: 10.5pt;\">&nbsp;<span style=\"font-family: 宋体;\">如何设置发票抬头</span></span></strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">&nbsp;<span style=\"font-family: 宋体;\">、</span></span><strong><span style=\"font-family: 宋体; color: #0000ff; font-size: 10.5pt;\">如何设置收件地址</span></strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">&nbsp;<span style=\"font-family: 宋体;\">。</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"font-family: Calibri; font-size: 10.5pt;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">操作步骤</span></strong></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">①登入 </span><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">&ldquo;会员中心&rdquo;</span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;<span style=\"font-family: 宋体;\">，点击</span> </span><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">&ldquo;发票管理&rdquo;</span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;<span style=\"font-family: 宋体;\">，选择</span> </span><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">&ldquo;发票列表&rdquo;</span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;<span style=\"font-family: 宋体;\">。</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">图</span><span style=\"font-family: Calibri;\">1</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><img src=\"data:image/png;base64,\" alt=\"\" /><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">②点击左上角 </span><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">&nbsp;<span style=\"font-family: 宋体;\">&ldquo;发票申请&rdquo;</span></span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;<span style=\"font-family: 宋体;\">。</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">图</span><span style=\"font-family: Calibri;\">2</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><img src=\"data:image/png;base64,\" alt=\"\" /><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">③在跳转页面，您可以选择 </span><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">&ldquo;后开票&rdquo; </span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">或</span> </span><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">&ldquo;预开票&rdquo;</span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;<span style=\"font-family: 宋体;\">。</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">后开票：已支付货款，确认收货后需要开具的发票。</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">预开票：未支付货款，生成订单后需要在付款前开具的发票。</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">图</span><span style=\"font-family: Calibri;\">3</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><img src=\"data:image/png;base64,\" alt=\"\" /><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">④勾选需要开具发票的产品后，点击左上角 </span><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">&ldquo;开具发票&rdquo;</span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;<span style=\"font-family: 宋体;\">。</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">图</span><span style=\"font-family: Calibri;\">4</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><img src=\"data:image/png;base64,\" alt=\"\" /><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-fareast-font-family: 宋体; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">⑤在弹窗页面根据字段提示填写相关信息，点击 </span><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">&ldquo;确认支付&rdquo;</span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;<span style=\"font-family: 宋体;\">即可。</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">图</span><span style=\"font-family: Calibri;\">5</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><img src=\"data:image/png;base64,\" alt=\"\" /><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-fareast-font-family: 宋体; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 130%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">⑥在</span><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">&nbsp;<span style=\"font-family: 宋体;\">&ldquo;发票列表&rdquo;</span></span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;<span style=\"font-family: 宋体;\">可查看已提交的发票申请与进度。</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">图</span><span style=\"font-family: Calibri;\">6</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 7.8500pt; mso-para-margin-bottom: 0.5000gd; text-autospace: ideograph-numeric; mso-pagination: none; text-align: center; line-height: 130%;\" align=\"center\"><img src=\"data:image/png;base64,\" alt=\"\" /><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-fareast-font-family: 宋体; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\n</body>\n</html>','','',0,0,2,1,1673342713,1674971925,0,0);
