insert  into `idcsmart_email_template`(`id`,`name`,`subject`,`message`,`attachment`,`create_time`,`update_time`) values (35,'对象存储联通异常通知','[{system_website_name}]对象存储联通异常通知','<!DOCTYPE html> <html lang=\"en\"> <head> <meta charset=\"UTF - 8\"> <meta http-equiv=\"X - UA - Compatible\" content=\"IE = edge\"> <meta name=\"viewport\" content=\"width = device - width, initial - scale = 1.0\"> <title>Document</title> <style> li{list-style: none;} a{text-decoration: none;} body{margin: 0;} .box{ background-color: #EBEBEB; height: 100%; } .logo_top {padding: 20px 0;} .logo_top img{ display: block; width: auto; margin: 0 auto; } .card{ width: 650px; margin: 0 auto; background-color: white; font-size: 0.8rem; line-height: 22px; padding: 40px 50px; box-sizing: border-box; } .contimg{ text-align: center; } button{ background-color: #F75697; padding: 8px 16px; border-radius: 6px; outline: none; color: white; border: 0; } .lvst{ color: #57AC80; } .banquan{ display: flex; justify-content: center; flex-wrap: nowrap; color: #B7B8B9; font-size: 0.4rem; padding: 20px 0; margin: 0; padding-left: 0; } .banquan li span{ display: inline-block; padding: 0 8px; } @media (max-width: 650px){ .card{ padding: 5% 5%; } .logo_top img,.contimg img{width: 280px;} .box{height: auto;} .card{width: auto;} } @media (max-width: 280px){.logo_top img,.contimg img{width: 100%;}} </style> </head> <body>\r\n<div class=\"box\">\r\n<div class=\"logo_top\"><img src=\"{\r\n        system_logo_url}\" alt=\"\" /></div>\r\n<div class=\"card\">\r\n<h2 style=\"text - align: center;\">[{system_website_name}]对象存储联通异常通知</h2>\r\n<br /><strong>尊敬的管理员</strong> <br /><span style=\"margin: 0; padding: 0; display: inline - block; margin - top: 55px;\">对象存储链接失败！请及时检查处理！<br /><span style=\"margin: 0; padding: 0; display: inline - block; margin - top: 60px;\">如果本次请求并非由您发起，请务必告知我们, 由此给您带来的不便敬请谅解。</span><br />&nbsp; <span style=\"margin: 0; padding: 0; display: inline - block; width: 100 %; text - align: right;\"> <strong>{system_website_name}</strong> </span><br /><span style=\"margin: 0; padding: 0; margin - top: 20px; display: inline - block; width: 100 %; text - align: right;\">{send_time}</span></div>\r\n<ul class=\"banquan\">\r\n<li>{system_website_name}</li>\r\n</ul>\r\n</div>\r\n</body> </html>','',0,0);
